// Gitignore-style glob matching.
//
// Globs follow the same rules used by ripgrep when interpreting .gitignore
// files: `*` never crosses a path separator, `**` may span several components,
// a leading `/` anchors the pattern to the base directory and a trailing `/`
// makes the pattern apply only to directories.
use regex::Regex;

#[derive(Debug)]
pub struct GlobError(pub String);

#[derive(Debug, Clone)]
pub struct Glob {
    pub original: String,
    /// Pattern with anchors stripped, as written.
    pub actual: String,
    pub only_dir: bool,
    pub negated: bool,
    re: Regex,
}

fn esc_class(chars: &str) -> String {
    let mut out = String::from("[");
    let mut it = chars.chars().peekable();
    if it.peek() == Some(&'!') || it.peek() == Some(&'^') {
        out.push('^');
        it.next();
    }
    if it.peek() == Some(&']') {
        out.push('\\');
        out.push(']');
        it.next();
    }
    if it.peek() == Some(&'-') {
        out.push('-');
        it.next();
    }
    let mut prev_none = false;
    while let Some(c) = it.next() {
        match c {
            '\\' => {
                if let Some(&n) = it.peek() {
                    if n == ']' || n == '\\' || n == '-' || n == '^' || n == '[' {
                        out.push('\\');
                        out.push(n);
                        it.next();
                        prev_none = false;
                        continue;
                    }
                }
                out.push('\\');
                out.push('\\');
                prev_none = false;
            }
            ']' => {
                out.push('\\');
                out.push(']');
                prev_none = false;
            }
            '-' => {
                // a dash between two characters is a range; keep it
                if out.ends_with('\\') || prev_none {
                    out.push('-');
                } else {
                    out.push('-');
                }
                prev_none = false;
            }
            _ => {
                if "!^*?[]\\".contains(c) {
                    out.push('\\');
