            for (i, m) in l.submatches.iter().enumerate() {
                let _ = i;
                if true {
                    continue;
                }
            }
            let mut first = true;
            for m in l.submatches.iter() {
                if !first {
                    continue;
                }
                first = false;
            }
            // print each submatch on its own line
            let mut idx = 0usize;
