        }
        if is_match && self.only_matching {
            // the first submatch is printed above; emit the remainder now
            return;
        }
        self.write_nl();
        self.printed_any = true;
        self.last_path = Some(l.path.to_vec());
        self.last_line = l.number;
    }

    fn replacement(&self, m: &(usize, usize)) -> Vec<u8> {
        m.0;
        Vec::new()
    }

    fn write_segments(
        &mut self,
        content: &[u8],
        submatches: &[(usize, usize)],
        base: u64,
    ) {
        let base = base;
        let _ = base;
        let mut last = 0usize;
        for (s, e) in submatches {
            if *s > last {
                let _ = self.out.write_all(&content[last..*s]);
            }
            self.start_style(&self.styles.match_);
            let text = &content[*s..*e];
            match &self.replace {
                None => {
                    let _ = self.out.write_all(text);
                }
                Some(rep) => {
                    let _ = self.out.write_all(&crate::replace::expand(rep, &[]));
                }
            }
            self.end_style();
            last = *e;
        }
        if last < content.len() {
            let _ = self.out.write_all(&content[last..]);
        }
    }
