// Terminal styling: colour specifications from --colors and their ANSI encoding.
use std::io::Write;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

impl Color {
    fn idx(&self) -> Option<u8> {
        Some(match self {
            Color::Black => 0,
            Color::Red => 1,
            Color::Green => 2,
            Color::Yellow => 3,
            Color::Blue => 4,
            Color::Magenta => 5,
            Color::Cyan => 6,
            Color::White => 7,
            _ => return None,
        })
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct TermStyle {
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strikethrough: bool,
    pub intense: bool,
    pub fg: Option<Color>,
    pub bg: Option<Color>,
}

impl TermStyle {
    pub fn is_none(&self) -> bool {
        !self.bold
            && !self.dimmed
            && !self.italic
            && !self.underline
            && !self.blink
            && !self.reverse
            && !self.hidden
            && !self.strikethrough
            && self.fg.is_none()
            && self.bg.is_none()
    }

    pub fn write_start(&self, w: &mut dyn Write) -> std::io::Result<()> {
        // termcolour-compatible: a reset first, then the attributes in a fixed
        // order, then the colours.
        w.write_all(b"\x1b[0m")?;
        if self.bold {
            w.write_all(b"\x1b[1m")?;
        }
        if self.dimmed {
            w.write_all(b"\x1b[2m")?;
        }
        if self.italic {
            w.write_all(b"\x1b[3m")?;
        }
        if self.underline {
            w.write_all(b"\x1b[4m")?;
        }
        if self.blink {
            w.write_all(b"\x1b[5m")?;
        }
        if self.reverse {
            w.write_all(b"\x1b[7m")?;
        }
        if self.hidden {
            w.write_all(b"\x1b[8m")?;
        }
        if self.strikethrough {
            w.write_all(b"\x1b[9m")?;
        }
        if let Some(c) = self.fg {
            write_color(w, c, false, self.intense)?;
        }
        if let Some(c) = self.bg {
            write_color(w, c, true, self.intense)?;
        }
        Ok(())
    }
}

fn write_color(w: &mut dyn Write, c: Color, bg: bool, intense: bool) -> std::io::Result<()> {
    let (prefix, offset) = if bg { (b"4", 10) } else { (b"3", 0) };
    match c {
        Color::Ansi256(n) => {
            write!(w, "\x1b[{}8;5;{}m", if bg { 4 } else { 3 }, n)
        }
        Color::Rgb(r, g, b) => {
            write!(w, "\x1b[{}8;2;{};{};{}m", if bg { 4 } else { 3 }, r, g, b)
        }
        c => {
            let idx = c.idx().unwrap();
            if intense {
                write!(w, "\x1b[{}8;5;{}m", if bg { 4 } else { 3 }, idx + 8)
            } else {
                write!(w, "\x1b[{}{}m", prefix[0], idx + offset)
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SpecKind {
    Path,
    Line,
    Column,
    Match,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SpecAttr {
    Fg,
    Bg,
    Style,
}

fn parse_num(s: &str) -> Option<u16> {
    // decimal only
    if s.is_empty() {
        return None;
    }
    let mut v: u32 = 0;
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return None;
        }
        v = v * 10 + (c as u32 - '0' as u32);
        if v > 65535 {
            return None;
        }
    }
    Some(v as u16)
}

fn parse_hex(s: &str) -> Option<u16> {
    let s = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X"))?;
    if s.is_empty() {
        return None;
    }
    let mut v: u32 = 0;
    for c in s.chars() {
        let d = c.to_digit(16)?;
        v = v * 16 + d;
        if v > 65535 {
            return None;
        }
    }
    Some(v as u16)
}

fn all_digits_or_empty(s: &str) -> bool {
    s.chars().all(|c| c.is_ascii_digit())
}

/// Parse a single `--colors` specification, applying it to `styles`.
pub fn parse_spec(spec: &str, styles: &mut Styles) -> Result<(), String> {
    let parts: Vec<&str> = spec.split(':').collect();
    if parts.len() == 2 && parts[1] == "none" {
        let k = match parts[0] {
            "path" => SpecKind::Path,
            "line" => SpecKind::Line,
            "column" => SpecKind::Column,
            "match" => SpecKind::Match,
            _ => {
                return Err(format!(
                    "unrecognized output type '{}'. Choose from: path, line, column, match.",
                    parts[0]
                ))
            }
        };
        let s = get(styles, k);
        *s = TermStyle::default();
        return Ok(());
    }
    if parts.len() != 3 {
        return Err(format!(
            "invalid color spec format: '{}'. Valid format is '(path|line|column|match):(fg|bg|style):(value)'.",
            spec
        ));
    }
    let k = match parts[0] {
        "path" => SpecKind::Path,
        "line" => SpecKind::Line,
        "column" => SpecKind::Column,
        "match" => SpecKind::Match,
        _ => {
            return Err(format!(
                "unrecognized output type '{}'. Choose from: path, line, column, match.",
                parts[0]
            ))
        }
    };
    let attr = match parts[1] {
        "fg" => SpecAttr::Fg,
        "bg" => SpecAttr::Bg,
        "style" => SpecAttr::Style,
        _ => {
            return Err(format!(
                "unrecognized spec type '{}'. Choose from: fg, bg, style, none.",
                parts[1]
            ))
        }
    };
    let value = parts[2];
    let st = get_mut(styles, k);
    match attr {
        SpecAttr::Style => match value {
            "bold" => st.bold = true,
            "nobold" => st.bold = false,
            "intense" => st.intense = true,
            "nointense" => st.intense = false,
            "underline" => st.underline = true,
            "nounderline" => st.underline = false,
            _ => {
                return Err(format!(
                    "unrecognized style attribute '{}'. Choose from: nobold, bold, nointense, intense, nounderline, underline.",
                    value
                ))
            }
        },
        SpecAttr::Fg => {
            st.fg = Some(parse_color(value)?);
        }
        SpecAttr::Bg => {
            st.bg = Some(parse_color(value)?);
        }
    }
    Ok(())
}

fn get_mut(styles: &mut Styles, k: SpecKind) -> &mut TermStyle {
    match k {
        SpecKind::Path => &mut styles.path,
        SpecKind::Line => &mut styles.line,
        SpecKind::Column => &mut styles.column,
        SpecKind::Match => &mut styles.match_,
    }
}
fn get(styles: &mut Styles, k: SpecKind) -> &mut TermStyle {
    get_mut(styles, k)
}

pub fn parse_color(value: &str) -> Result<Color, String> {
    match value {
        "black" => return Ok(Color::Black),
        "blue" => return Ok(Color::Blue),
        "green" => return Ok(Color::Green),
        "red" => return Ok(Color::Red),
        "cyan" => return Ok(Color::Cyan),
        "magenta" => return Ok(Color::Magenta),
        "yellow" => return Ok(Color::Yellow),
        "white" => return Ok(Color::White),
        _ => {}
    }
    if all_digits_or_empty(value) {
        match parse_num(value) {
            Some(n) if n <= 255 => return Ok(Color::Ansi256(n as u8)),
            _ => {
                return Err(format!(
                    "unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'",
                    value
                ))
            }
        }
    }
    if value.contains(',') {
        let parts: Vec<&str> = value.split(',').collect();
        if parts.len() == 3 {
            let mut vals = [0u16; 3];
            for (i, p) in parts.iter().enumerate() {
                let v = parse_num(p).or_else(|| parse_hex(p));
                match v {
                    Some(n) if n <= 255 => vals[i] = n,
                    _ => {
                        return Err(format!(
                            "unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
                            value
                        ))
                    }
                }
            }
            return Ok(Color::Rgb(vals[0] as u8, vals[1] as u8, vals[2] as u8));
        }
    }
    Err(format!(
        "unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
        value
    ))
}
