fn parse_num(s: &str) -> Option<u16> {
    // decimal only
    if s.is_empty() {
        return None;
    }
    let mut v: u32 = 0;
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return None;
        }
        v = v * 10 + (c as u32 - '0' as u32);
        if v > 65535 {
            return None;
        }
    }
    Some(v as u16)
}

fn parse_hex(s: &str) -> Option<u16> {
    let s = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X"))?;
    if s.is_empty() {
        return None;
    }
    let mut v: u32 = 0;
    for c in s.chars() {
        let d = c.to_digit(16)?;
