        "default" | "file" => "file://{host}{path}",
        "none" => "",
        "grep+" => "grep+://{path}:{line}",
        "kitty" => "file://{host}{path}#{line}",
        "macvim" => "mvim://open?url=file://{path}&line={line}&column={column}",
        "textmate" => "txmt://open?url=file://{path}&line={line}&column={column}",
        "vscode" => "vscode://file{path}:{line}:{column}",
        "vscode-insiders" => "vscode-insiders://file{path}:{line}:{column}",
        "vscodium" => "vscodium://file{path}:{line}:{column}",
        _ => return None,
    })
}

#[derive(Debug, Clone)]
pub struct Hyperlink {
    pub fmt: String,
    pub host: String,
}

fn is_scheme_start(fmt: &str) -> bool {
    let bytes = fmt.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i] as char;
        if c == ':' {
            return i > 0;
        }
        if !(c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
            return false;
        }
        i += 1;
    }
    false
}

impl Hyperlink {
    /// Validate a format string (after alias expansion).
    pub fn validate(fmt: &str) -> Result<(), String> {
        if fmt.is_empty() {
            return Ok(());
        }
        if !is_scheme_start(fmt) {
            return Err(
                "invalid hyperlink format: the hyperlink format must start with a valid URL scheme, i.e., [0-9A-Za-z+-.]+:"
                    .to_string(),
            );
        }
        if !fmt.contains("{path}") {
            return Err(
                "invalid hyperlink format: at least a {path} variable is required in a hyperlink format, or otherwise use a valid alias: default, file, grep+, kitty, macvim, none, textmate, vscode, vscode-insiders, vscodium"
                    .to_string(),
            );
        }
        Ok(())
    }

    pub fn url(&self, path: &[u8], line: Option<u64>, column: Option<u64>) -> Vec<u8> {
        let mut out = Vec::new();
        let fmt = &self.fmt;
        let mut i = 0;
        let bytes = fmt.as_bytes();
        while i < bytes.len() {
            if bytes[i] == b'{' {
                let close = fmt[i..].find('}');
                if let Some(off) = close {
                    let name = &fmt[i + 1..i + off];
                    match name {
                        "path" => {
                            out.extend(percent_encode(path));
                        }
                        "host" => {
                            out.extend(self.host.as_bytes());
                        }
                        "line" => {
                            out.extend(line.unwrap_or(1).to_string().as_bytes());
                        }
                        "column" => {
                            out.extend(column.unwrap_or(1).to_string().as_bytes());
                        }
                        "wslprefix" => {}
                        _ => {
                            out.extend(name.as_bytes());
                        }
                    }
                    i += off + 1;
                    continue;
                }
            }
            out.push(bytes[i]);
            i += 1;
        }
        out
    }
}

fn percent_encode(path: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(path.len());
    for &b in path {
        let c = b as char;
        let keep = c.is_ascii_alphanumeric() || matches!(c, '-' | '.' | '_' | '~' | '/') || b >= 0x80;
        if keep {
            out.push(b);
        } else {
            out.push(b'%');
            out.push(b"0123456789ABCDEF"[(b >> 4) as usize]);
            out.push(b"0123456789ABCDEF"[(b & 0xf) as usize]);
        }
    }
    out
}

/// Write `path` wrapped in hyperlink escape codes when enabled.
pub fn write_path<W: Write>(
    w: &mut W,
    link: Option<&Hyperlink>,
    path: &[u8],
) -> std::io::Result<()> {
    if let Some(h) = link {
        if !h.fmt.is_empty() {
            let url = h.url(path, None, None);
            w.write_all(b"\x1b]8;;")?;
            w.write_all(&url)?;
            w.write_all(b"\x1b\\")?;
            w.write_all(path)?;
            w.write_all(b"\x1b]8;;")?;
            w.write_all(b"\x1b\\")?;
            return Ok(());
        }
    }
    w.write_all(path)
}
