// Output printers.
use std::io::Write;

use crate::hyper::{self, Hyperlink};
use crate::search::Line;
use crate::text::{write_start, Styles};

/// The different ways ripgrep can present search results.
pub enum Printer<W: Write> {
    Std(StdPrinter<W>),
    Json(JsonPrinter<W>),
    /// -c/--count and --count-matches
    Count(CountPrinter<W>, bool),
    /// -l/--files-with-matches and --files-without-match
    Files(FilesPrinter<W>),
    /// -q/--quiet
    Quiet(QuietPrinter<W>),
}

pub struct StdPrinter<W: Write> {
    pub out: W,
    pub styles: Styles,
    pub color: bool,
    pub with_filename: bool,
    pub heading: bool,
    pub line_number: bool,
    pub column: bool,
    pub byte_offset: bool,
    pub replace: Option<Vec<u8>>,
    pub max_columns: Option<u64>,
    pub max_columns_preview: bool,
    pub trim: bool,
    pub path_sep: Vec<u8>,
    pub field_match_sep: Vec<u8>,
    pub field_context_sep: Vec<u8>,
    pub context_sep: Option<Vec<u8>>,
    pub term: Vec<u8>,
    pub null: bool,
    pub only_matching: bool,
    pub hyperlink: Option<Hyperlink>,
    last_path: Option<Vec<u8>>,
    last_line: u64,
    printed_any: bool,
    pub bytes_printed: u64,
    pub lines_printed: u64,
}

impl<W: Write> StdPrinter<W> {
    pub fn new(out: W) -> StdPrinter<W> {
        StdPrinter {
            out,
            styles: Styles::default(),
            color: false,
            with_filename: false,
            heading: false,
            line_number: false,
            column: false,
            byte_offset: false,
            replace: None,
            max_columns: None,
            max_columns_preview: false,
            trim: false,
            path_sep: b":".to_vec(),
            field_match_sep: b":".to_vec(),
            field_context_sep: b"-".to_vec(),
            context_sep: Some(b"--".to_vec()),
            term: b"\n".to_vec(),
            null: false,
            only_matching: false,
            hyperlink: None,
            last_path: None,
            last_line: 0,
            printed_any: false,
            bytes_printed: 0,
            lines_printed: 0,
        }
    }

    fn emit(&mut self, bytes: &[u8]) {
        let _ = self.out.write_all(bytes);
        self.bytes_printed += bytes.len() as u64;
    }
    fn emit_nl(&mut self) {
        self.emit(b"\n");
    }

    fn maybe_separator(&mut self, path: &[u8], line_no: u64) {
        if !self.printed_any {
            return;
        }
        let new_file = self.last_path.as_deref() != Some(path);
        if self.heading {
            if new_file {
                return;
            }
            if self.last_line != 0 && line_no != self.last_line + 1 {
                if let Some(s) = &self.context_sep {
                    self.emit(s);
                }
                self.emit_nl();
            }
            return;
        }
        if new_file || (self.last_line != 0 && line_no != self.last_line + 1) {
            if let Some(s) = &self.context_sep {
                self.emit(s);
            }
            self.emit_nl();
        }
    }

    fn maybe_heading(&mut self, path: &[u8]) {
        if !self.heading || !self.with_filename {
            return;
        }
        if self.printed_any {
            self.emit_nl();
        }
        self.start_style(&self.styles.path);
        let _ = hyper::write_path(&mut self.out, self.hyperlink.as_ref(), path);
        self.end_style();
        if self.null {
            self.emit(b"\x00");
        }
        self.emit_nl();
        self.last_path = Some(path.to_vec());
        self.last_line = 0;
    }

    fn start_style(&mut self, s: &crate::text::TermStyle) {
        if !self.color {
            return;
        }
        let _ = write_start(&mut self.out, s);
        self.bytes_printed += crate::text::style_len(s);
    }
    fn end_style(&mut self) {
        if !self.color {
            return;
        }
        let _ = self.out.write_all(b"\x1b[0m");
        self.bytes_printed += 4;
    }

    fn print_fields(&mut self, l: &Line, is_match: bool) {
        let sep = if is_match {
            &self.field_match_sep
        } else {
            &self.field_context_sep
        };
        if self.with_filename && !self.heading {
            self.start_style(&self.styles.path);
            let _ = hyper::write_path(&mut self.out, self.hyperlink.as_ref(), &l.path);
            self.end_style();
            if self.null {
                self.emit(b"\x00");
            }
            self.emit(sep);
        }
        if self.line_number {
            self.start_style(&self.styles.line);
            let n = l.number.to_string();
            self.emit(n.as_bytes());
            self.end_style();
            self.emit(sep);
        }
        if self.column {
            if let Some(col) = l.column {
                self.start_style(&self.styles.column);
                let n = col.to_string();
                self.emit(n.as_bytes());
                self.end_style();
                self.emit(sep);
            }
        }
        if self.byte_offset {
            self.start_style(&self.styles.column);
            let n = l.offset.to_string();
            self.emit(n.as_bytes());
            self.end_style();
            self.emit(sep);
        }
    }

    fn print_content(&mut self, l: &Line, is_match: bool) {
        let mut content: &[u8] = &l.bytes;
        if self.trim {
            let mut i = 0;
            while i < content.len() && content[i].is_ascii_whitespace() {
                i += 1;
            }
            content = &content[i..];
        }
        if let Some(limit) = self.max_columns {
            if limit > 0 && content.len() > limit as usize {
                if self.max_columns_preview {
                    self.emit(&content[..limit as usize]);
                    self.emit(b" [... omitted end of long line]");
                } else {
                    self.emit(b"[Omitted long matching line]");
                }
                return;
            }
        }
        if !is_match {
            self.emit(content);
            return;
        }
        if self.only_matching {
            self.start_style(&self.styles.match_);
            match &self.replace {
                None => self.emit(&l.bytes),
                Some(rep) => self.emit(&crate::replace::expand(
                    rep,
                    &l.caps,
                    &l.matched_text,
                    self.styles.match_.fg.is_some(),
                )),
            }
            self.end_style();
            return;
        }
        let mut last = 0usize;
        for (s, e) in &l.submatches {
            if *s > last {
                self.emit(&l.bytes[last..*s]);
            }
            self.start_style(&self.styles.match_);
            match &self.replace {
                None => self.emit(&l.bytes[*s..*e]),
                Some(rep) => self.emit(&crate::replace::expand(
                    rep,
                    &l.caps,
                    &l.matched_text,
                    self.styles.match_.fg.is_some(),
                )),
            }
            self.end_style();
            last = *e;
        }
        if last < l.bytes.len() {
            self.emit(&l.bytes[last..]);
        }
    }
}

pub struct JsonPrinter<W: Write> {
    pub out: W,
    pub bytes_printed: u64,
    started: bool,
    path: Vec<u8>,
}

impl<W: Write> JsonPrinter<W> {
    pub fn new(out: W) -> JsonPrinter<W> {
        JsonPrinter {
            out,
            bytes_printed: 0,
            started: false,
            path: Vec::new(),
        }
    }
    fn emit_json(&mut self, s: &str) {
        let _ = self.out.write_all(s.as_bytes());
        let _ = self.out.write_all(b"\n");
        self.bytes_printed += s.len() as u64 + 1;
    }
    fn begin(&mut self, l: &Line) {
        if self.started {
            return;
        }
        self.started = true;
        self.path = l.path.clone();
        self.emit_json(&format!(
            "{{\"type\":\"begin\",\"data\":{{\"path\":{}}}}}",
            json_value(&l.path)
        ));
    }
}

pub struct CountPrinter<W: Write> {
    pub out: W,
    pub with_filename: bool,
    pub null: bool,
    pub count: u64,
    pub path: Vec<u8>,
    pub printed: bool,
    pub bytes_printed: u64,
}

pub struct FilesPrinter<W: Write> {
    pub out: W,
    pub without_match: bool,
    pub null: bool,
    pub path: Vec<u8>,
    pub had_match: bool,
    pub printed: bool,
    pub bytes_printed: u64,
}

pub struct QuietPrinter<W: Write> {
    pub out: W,
    pub had_match: bool,
}

impl<W: Write> Printer<W> {
    pub fn begin(&mut self, path: &[u8]) {
        match self {
            Printer::Json(p) => {
                p.path = path.to_vec();
            }
            Printer::Std(p) => {
                // in heading mode the path heading is printed lazily
                p.last_path = None;
                p.last_line = 0;
            }
            _ => {}
        }
    }
    pub fn match_line(&mut self, l: &Line) {
        match self {
            Printer::Std(p) => {
                p.maybe_separator(&l.path, l.number);
                p.maybe_heading(&l.path);
                p.print_fields(l, true);
                p.print_content(l, true);
                p.emit_nl();
                p.printed_any = true;
                p.last_path = Some(l.path.clone());
                p.last_line = l.number;
                p.lines_printed += 1;
            }
            Printer::Json(p) => {
                p.begin(l);
                let subs: Vec<String> = l
                    .submatches
                    .iter()
                    .map(|(s, e)| {
                        format!(
                            "{{\"match\":{},\"start\":{},\"end\":{}}}",
                            json_value(&l.bytes[*s..*e]),
                            s,
                            e
                        )
                    })
                    .collect();
                p.emit_json(&format!(
                    "{{\"type\":\"match\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[{}]}}}}",
                    json_value(&l.path),
                    json_value(&l.line_text),
                    l.number,
                    l.offset,
                    subs.join(",")
                ));
            }
            Printer::Count(p, _) => {
                p.count += 1;
            }
            Printer::Files(p) => {
                if !p.had_match {
                    p.had_match = true;
                    if !p.without_match && !p.printed {
                        p.printed = true;
                        let _ = p.out.write_all(&p.path);
                        if p.null {
                            let _ = p.out.write_all(b"\x00");
                        }
                        let _ = p.out.write_all(b"\n");
                        p.bytes_printed += p.path.len() as u64 + 1;
                    }
                }
            }
            Printer::Quiet(p) => {
                p.had_match = true;
            }
        }
    }
    pub fn context_line(&mut self, l: &Line) {
        match self {
            Printer::Std(p) => {
                p.maybe_separator(&l.path, l.number);
                p.maybe_heading(&l.path);
                p.print_fields(l, false);
                p.print_content(l, false);
                p.emit_nl();
                p.printed_any = true;
                p.last_path = Some(l.path.clone());
                p.last_line = l.number;
            }
            Printer::Json(p) => {
                p.begin(l);
                p.emit_json(&format!(
                    "{{\"type\":\"context\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[]}}}}",
                    json_value(&l.path),
                    json_value(&l.line_text),
                    l.number,
                    l.offset
                ));
            }
            _ => {}
        }
    }
    pub fn binary(&mut self, offset: u64) {
        match self {
            Printer::Std(p) => {
                let msg = format!(
                    "binary file matches (found \"\\0\" byte around offset {})",
                    offset
                );
                p.emit(msg.as_bytes());
                p.emit_nl();
            }
            _ => {}
        }
    }
    pub fn end_file(&mut self, path: &[u8], had_match: bool, binary_offset: Option<u64>) {
        match self {
            Printer::Std(p) => {}
            Printer::Json(p) => {
                if p.started {
                    p.emit_json(&format!(
                        "{{\"type\":\"end\",\"data\":{{\"path\":{},\"binary_offset\":{},\"stats\":{{}}}}}}",
                        json_value(path),
                        match binary_offset {
                            None => "null".to_string(),
                            Some(o) => o.to_string(),
                        }
                    ));
                }
            }
            Printer::Count(p, with_path) => {
                if had_match || *with_path {
                    if p.with_filename || *with_path {
                        let _ = p.out.write_all(path);
                        if p.null {
                            let _ = p.out.write_all(b"\x00");
                        }
                        let _ = p.out.write_all(b":");
                    }
                    let c = p.count.to_string();
                    let _ = p.out.write_all(c.as_bytes());
                    let _ = p.out.write_all(b"\n");
                }
            }
            Printer::Files(p) => {
                if p.without_match && !p.had_match && !p.printed {
                    p.printed = true;
                    let _ = p.out.write_all(path);
                    if p.null {
                        let _ = p.out.write_all(b"\x00");
                    }
                    let _ = p.out.write_all(b"\n");
                }
            }
            Printer::Quiet(_) => {}
        }
    }
    pub fn flush(&mut self) {
        match self {
            Printer::Std(p) => {
                let _ = p.out.flush();
            }
            Printer::Json(p) => {
                let _ = p.out.flush();
            }
            Printer::Count(p, _) => {
                let _ = p.out.flush();
            }
            Printer::Files(p) => {
                let _ = p.out.flush();
            }
            Printer::Quiet(_) => {}
        }
    }
    pub fn bytes_printed(&self) -> u64 {
        match self {
            Printer::Std(p) => p.bytes_printed,
            Printer::Json(p) => p.bytes_printed,
            Printer::Count(p, _) => p.bytes_printed,
            Printer::Files(p) => p.bytes_printed,
            Printer::Quiet(_) => 0,
        }
    }
    pub fn had_match(&self) -> bool {
        match self {
            Printer::Quiet(p) => p.had_match,
            _ => false,
        }
    }
}

pub fn json_value(bytes: &[u8]) -> String {
    match std::str::from_utf8(bytes) {
        Ok(s) => {
            let mut out = String::from("{\"text\":");
            out.push_str(&json_escape(s));
            out.push('}');
            out
        }
        Err(_) => {
            let mut out = String::from("{\"bytes\":\"");
            for b in crate::b64::encode(bytes) {
                out.push(b as char);
            }
            out.push_str("\"}");
            out
        }
    }
}

pub fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
