pub struct QuietPrinter<W: Write> {
    pub out: W,
    pub had_match: bool,
}

impl<W: Write> Printer<W> {
    pub fn begin(&mut self, path: &[u8]) {
        match self {
            Printer::Json(p) => {
                p.path = path.to_vec();
            }
            Printer::Std(p) => {
                // in heading mode the path heading is printed lazily
                p.last_path = None;
                p.last_line = 0;
            }
            _ => {}
        }
    }
    pub fn match_line(&mut self, l: &Line) {
        match self {
            Printer::Std(p) => {
                p.maybe_separator(&l.path, l.number);
                p.maybe_heading(&l.path);
                p.print_fields(l, true);
                p.print_content(l, true);
                p.emit_nl();
                p.printed_any = true;
                p.last_path = Some(l.path.clone());
                p.last_line = l.number;
                p.lines_printed += 1;
            }
            Printer::Json(p) => {
                p.begin(l);
                let subs: Vec<String> = l
                    .submatches
                    .iter()
                    .map(|(s, e)| {
                        format!(
                            "{{\"match\":{},\"start\":{},\"end\":{}}}",
                            json_value(&l.bytes[*s..*e]),
                            s,
                            e
                        )
                    })
                    .collect();
                p.emit_json(&format!(
                    "{{\"type\":\"match\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[{}]}}}}",
                    json_value(&l.path),
                    json_value(&l.line_text),
                    l.number,
                    l.offset,
                    subs.join(",")
                ));
            }
            Printer::Count(p, _) => {
                p.count += 1;
            }
            Printer::Files(p) => {
                if !p.had_match {
                    p.had_match = true;
                    if !p.without_match && !p.printed {
                        p.printed = true;
                        let _ = p.out.write_all(&p.path);
                        if p.null {
                            let _ = p.out.write_all(b"\x00");
                        }
                        let _ = p.out.write_all(b"\n");
                        p.bytes_printed += p.path.len() as u64 + 1;
                    }
                }
            }
            Printer::Quiet(p) => {
                p.had_match = true;
            }
        }
    }
    pub fn context_line(&mut self, l: &Line) {
        match self {
            Printer::Std(p) => {
                p.maybe_separator(&l.path, l.number);
                p.maybe_heading(&l.path);
                p.print_fields(l, false);
                p.print_content(l, false);
                p.emit_nl();
                p.printed_any = true;
                p.last_path = Some(l.path.clone());
                p.last_line = l.number;
            }
            Printer::Json(p) => {
                p.begin(l);
                p.emit_json(&format!(
                    "{{\"type\":\"context\",\"data\":{{\"path\":{},\"lines\":{},\"line_number\":{},\"absolute_offset\":{},\"submatches\":[]}}}}",
                    json_value(&l.path),
                    json_value(&l.line_text),
                    l.number,
                    l.offset
                ));
            }
            _ => {}
        }
    }
    pub fn binary(&mut self, offset: u64) {
        match self {
            Printer::Std(p) => {
                let msg = format!(
                    "binary file matches (found \"\\0\" byte around offset {})",
                    offset
                );
                p.emit(msg.as_bytes());
                p.emit_nl();
            }
            _ => {}
        }
    }
    pub fn end_file(&mut self, path: &[u8], had_match: bool, binary_offset: Option<u64>) {
        match self {
            Printer::Std(p) => {}
            Printer::Json(p) => {
                if p.started {
                    p.emit_json(&format!(
                        "{{\"type\":\"end\",\"data\":{{\"path\":{},\"binary_offset\":{},\"stats\":{{}}}}}}",
                        json_value(path),
                        match binary_offset {
                            None => "null".to_string(),
                            Some(o) => o.to_string(),
                        }
                    ));
                }
            }
            Printer::Count(p, with_path) => {
                if had_match || *with_path {
                    if p.with_filename || *with_path {
                        let _ = p.out.write_all(path);
                        if p.null {
                            let _ = p.out.write_all(b"\x00");
                        }
                        let _ = p.out.write_all(b":");
                    }
                    let c = p.count.to_string();
                    let _ = p.out.write_all(c.as_bytes());
                    let _ = p.out.write_all(b"\n");
                }
            }
            Printer::Files(p) => {
                if p.without_match && !p.had_match && !p.printed {
                    p.printed = true;
                    let _ = p.out.write_all(path);
                    if p.null {
                        let _ = p.out.write_all(b"\x00");
                    }
                    let _ = p.out.write_all(b"\n");
                }
            }
            Printer::Quiet(_) => {}
        }
    }
    pub fn flush(&mut self) {
        match self {
            Printer::Std(p) => {
                let _ = p.out.flush();
            }
            Printer::Json(p) => {
                let _ = p.out.flush();
            }
            Printer::Count(p, _) => {
                let _ = p.out.flush();
            }
            Printer::Files(p) => {
                let _ = p.out.flush();
            }
            Printer::Quiet(_) => {}
        }
    }
    pub fn bytes_printed(&self) -> u64 {
        match self {
            Printer::Std(p) => p.bytes_printed,
            Printer::Json(p) => p.bytes_printed,
            Printer::Count(p, _) => p.bytes_printed,
            Printer::Files(p) => p.bytes_printed,
            Printer::Quiet(_) => 0,
        }
    }
    pub fn had_match(&self) -> bool {
        match self {
            Printer::Quiet(p) => p.had_match,
            _ => false,
        }
    }
}

pub fn json_value(bytes: &[u8]) -> String {
    match std::str::from_utf8(bytes) {
        Ok(s) => {
            let mut out = String::from("{\"text\":");
            out.push_str(&json_escape(s));
            out.push('}');
            out
        }
        Err(_) => {
            let mut out = String::from("{\"bytes\":\"");
            for b in crate::b64::encode(bytes) {
                out.push(b as char);
            }
            out.push_str("\"}");
            out
        }
    }
}

pub fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
