    pub line_text: Vec<u8>,
    pub submatches: Vec<(usize, usize)>,
    pub caps: Vec<Option<(usize, usize)>>,
    pub matched_text: Vec<u8>,
}

#[derive(Default, Clone, Copy)]
pub struct Stats {
    pub searches: u64,
    pub search_with_match: bool,
    pub bytes_searched: u64,
    pub matched_lines: u64,
    pub matches: u64,
}

pub trait Sink {
    fn match_line(&mut self, l: &Line);
    fn context_line(&mut self, l: &Line);
    fn binary(&mut self, offset: u64);
    fn end_file(&mut self, path: &[u8], had_match: bool, binary_offset: Option<u64>, st: &Stats);
}

pub struct Searcher<'a> {
    pub matcher: &'a crate::matcher::Matcher,
    pub crlf: bool,
    pub null_data: bool,
    pub max_count: u64,
    pub invert: bool,
    pub stop_on_nonmatch: bool,
    pub passthru: bool,
    pub before: u64,
    pub after: u64,
    pub text_mode: bool,
    pub only_matching: bool,
    pub column: bool,
    pub byte_offset: bool,
    pub multiline: bool,
    pub multiline_dotall: bool,
    pub stop_on_first: bool,
}

impl<'a> Searcher<'a> {
    pub fn new(m: &'a crate::matcher::Matcher) -> Searcher<'a> {
        Searcher {
            matcher: m,
            crlf: false,
            null_data: false,
            max_count: u64::MAX,
            invert: false,
            stop_on_nonmatch: false,
            passthru: false,
            before: 0,
            after: 0,
            text_mode: false,
            only_matching: false,
            column: false,
            byte_offset: false,
            multiline: false,
            multiline_dotall: false,
            stop_on_first: false,
        }
    }

    fn find_in(&self, buf: &[u8]) -> Vec<crate::matcher::MMatch> {
        self.matcher.find_iter(buf)
    }

    /// Search a reader (a file or standard input).
    pub fn search_reader(
        &self,
        path: &[u8],
        rdr: &mut dyn Read,
        sink: &mut dyn Sink,
        is_file: bool,
    ) -> Result<Stats, std::io::Error> {
        let mut st = Stats::default();
        st.searches = 1;
        let mut buf: Vec<u8> = Vec::with_capacity(WINDOW);
        let mut base: u64 = 0;
        let mut eof = false;
        let mut line_no: u64 = 0;
        let mut matched_lines: u64 = 0;
        let mut matches: u64 = 0;
        let mut pending: std::collections::VecDeque<(Vec<u8>, Vec<u8>)> =
            std::collections::VecDeque::new();
        let mut after_remaining: u64 = 0;
        let mut binary_offset: Option<u64> = None;
        let mut suppressed = false;
        let mut first_window = true;
        let mut seen_match = false;
        let mut count: u64 = 0;

        let term_nul = self.null_data;
        let crlf = self.crlf && !term_nul;

        loop {
            if !eof && buf.len() < WINDOW {
                let mut chunk = vec![0u8; WINDOW - buf.len()];
                match rdr.read(&mut chunk) {
                    Ok(0) => eof = true,
                    Ok(n) => {
                        buf.extend_from_slice(&chunk[..n]);
                        if buf.len() < WINDOW {
                            continue;
                        }
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(e) => return Err(e),
                }
            } else if !eof {
                // window full; read more so that long lines can be handled
                let mut chunk = vec![0u8; WINDOW];
                match rdr.read(&mut chunk) {
                    Ok(0) => eof = true,
                    Ok(n) => buf.extend_from_slice(&chunk[..n]),
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(e) => return Err(e),
                }
            }
            if first_window && !self.text_mode {
                first_window = false;
                if let Some(p) = memchr_byte(&buf, b'\0') {
                    binary_offset = Some(base + p as u64);
                    suppressed = true;
                }
            }
            // Determine how much of the buffer can be processed: up to and
            // including the last complete line terminator.
            let end = last_terminator(&buf, crlf, term_nul);
            match end {
                Some(e) => {
                    let region = &buf[..e];
                    let n = self.process_region(
                        path,
                        region,
                        base,
                        &mut line_no,
                        &mut matched_lines,
                        &mut matches,
                        &mut pending,
                        &mut after_remaining,
                        &mut suppressed,
                        binary_offset,
                        &mut count,
                        &mut seen_match,
                        sink,
                    )?;
                    st.bytes_searched = base + e as u64;
                    if suppressed {
                        if let Some(b) = binary_offset {
                            if is_file {
                                st.bytes_searched = b;
                            }
                        }
                    }
                    base += e as u64;
                    buf.drain(..e);
                }
                None => {
                    if eof {
                        let n = buf.len();
                        if n > 0 {
                            self.process_region(
                                path,
                                &buf[..],
                                base,
                                &mut line_no,
                                &mut matched_lines,
                                &mut matches,
                                &mut pending,
                                &mut after_remaining,
                                &mut suppressed,
                                binary_offset,
                                &mut count,
                                &mut seen_match,
                                sink,
                            )?;
                            st.bytes_searched = base + n as u64;
                            if suppressed {
                                if let Some(b) = binary_offset {
                                    if is_file {
                                        st.bytes_searched = b;
                                    }
                                }
                            }
                            base += n as u64;
                            buf.clear();
                        }
                        break;
                    } else {
                        continue;
                    }
                }
            }
            if self.stop_on_first && count > 0 {
                break;
            }
            if count >= self.max_count {
                break;
            }
        }
        st.matched_lines = matched_lines;
        st.matches = matches;
        st.search_with_match = matches > 0 || matched_lines > 0 || binary_offset.is_some();
        if !suppressed {
            if let Some(b) = binary_offset {
                sink.binary(b);
            }
        } else if let Some(b) = binary_offset {
            sink.binary(b);
        }
        sink.end_file(path, st.search_with_match, binary_offset, &st);
        Ok(st)
    }

    #[allow(clippy::too_many_arguments)]
    fn process_region(
        &self,
        path: &[u8],
        region: &[u8],
        base: u64,
        line_no: &mut u64,
        matched_lines: &mut u64,
        matches: &mut u64,
        pending: &mut std::collections::VecDeque<(Vec<u8>, Vec<u8>)>,
        after_remaining: &mut u64,
        suppressed: &mut bool,
        _binary_offset: Option<u64>,
        count: &mut u64,
        seen_match: &mut bool,
        sink: &mut dyn Sink,
    ) -> Result<(), std::io::Error> {
        let mut pos = 0usize;
        while pos < region.len() {
            let (term_start, term_len) = find_terminator(&region[pos..], self.crlf, self.null_data);
            let (content, term_bytes) = match term_start {
                Some(t) => (&region[pos..pos + t], region[pos + t..pos + t + term_len].to_vec()),
                None => (region[pos..], Vec::new()),
            };
            *line_no += 1;
            let number = *line_no;
            let offset = base + pos as u64;
            let mut m = Line {
                path: path.to_vec(),
                number,
                offset,
                column: None,
                bytes: content.to_vec(),
                line_text: {
                    let mut v = content.to_vec();
                    v.extend_from_slice(&term_bytes);
                    v
                },
                submatches: Vec::new(),
                caps: Vec::new(),
                matched_text: Vec::new(),
            };
            let found = self.find_in(&m.bytes);
            let is_match = if self.invert {
                found.is_empty()
            } else {
                !found.is_empty()
            };
            if is_match {
                *matched_lines += 1;
            }
            let has_line_match = if self.passthru {
                !found.is_empty()
            } else {
                is_match
            };
            if has_line_match && !*suppressed && !self.text_mode {
                // binary detection: does the line contain a NUL byte?
                if memchr_byte(&m.bytes, b'\0').is_some() {
                    if let Some(p) = memchr_byte(&m.bytes, b'\0') {
                        // binary_offset is the absolute offset of the NUL
                        let off = offset + p as u64;
                        if _binary_offset.is_none() {
                            *suppressed = true;
                            sink.binary(off);
                        }
                    }
                }
            }
            if has_line_match {
                *seen_match = true;
                if !*suppressed {
                    // before context
                    for (b, bo) in pending.drain(..) {
                        let cl = Line {
                            path: path.to_vec(),
                            number: *line_no - 0,
                            offset: bo,
                            column: None,
                            bytes: b.clone(),
                            line_text: b,
                            submatches: Vec::new(),
                            caps: Vec::new(),
                            matched_text: Vec::new(),
                        };
                        let cl = cl;
                        let mut cl2 = cl;
                        // line numbers are recomputed below
                        cl2.number = number_of(pending, bo, base);
                        sink.context_line(&cl2);
                    }
                }
                pending.clear();
                if !*suppressed {
                    self.emit_match(sink, &m, &found, offset);
                    *count += 1;
                }
                *matches += found.len() as u64;
                *after_remaining = self.after;
                if self.stop_on_first && *count >= 1 {
                    return Ok(());
                }
                if *count >= self.max_count {
                    return Ok(());
            }
            } else {
                if self.passthru {
                    if !*suppressed {
                        sink.context_line(&m);
                    }
                } else if *after_remaining > 0 {
                    if !*suppressed {
                        sink.context_line(&m);
                    }
                    *after_remaining -= 1;
                } else {
                    if self.stop_on_nonmatch && *seen_match {
                        return Ok(());
                    }
                    pending.push_back((m.bytes.clone(), offset));
                    while pending.len() > self.before as usize {
                        pending.pop_front();
                    }
                }
            }
            pos += content.len() + term_bytes.len();
            if term_bytes.is_empty() {
                break;
            }
        }
        Ok(())
    }

    fn emit_match(
        &self,
        sink: &mut dyn Sink,
        m: &Line,
        found: &[crate::matcher::MMatch],
        offset: u64,
    ) {
        if self.only_matching {
            for f in found {
                let mut l = Line {
                    path: m.path.clone(),
                    number: m.number,
                    offset: offset + f.start as u64,
                    column: Some(f.start as u64 + 1),
                    bytes: m.bytes[f.start..f.end].to_vec(),
                    line_text: m.line_text.clone(),
                    submatches: vec![(0, f.end - f.start)],
                    caps: f.caps.clone(),
                    matched_text: m.bytes[f.start..f.end].to_vec(),
                };
                if self.column {
                    l.column = Some(f.start as u64 + 1);
                }
                sink.match_line(&l);
            }
            return;
        }
        let mut l = Line {
            path: m.path.clone(),
            number: m.number,
            offset: m.offset,
            column: if self.column {
                found.first().map(|f| f.start as u64 + 1)
            } else {
                None
            },
            bytes: m.bytes.clone(),
            line_text: m.line_text.clone(),
            submatches: found.iter().map(|f| (f.start, f.end)).collect(),
            caps: found.first().map(|f| f.caps.clone()).unwrap_or_default(),
            matched_text: found
                .first()
                .map(|f| m.bytes[f.start..f.end].to_vec())
                .unwrap_or_default(),
        };
        if self.byte_offset && self.only_matching {
            l.offset = offset;
        }
        sink.match_line(&l);
    }
}

fn number_of(_pending: &std::collections::VecDeque<(Vec<u8>, Vec<u8>)>, _off: u64, _base: u64) -> u64 {
    0
}

pub fn memchr_byte(buf: &[u8], needle: u8) -> Option<usize> {
    buf.iter().position(|&b| b == needle)
}

/// Find the last complete line terminator in `buf`.
fn last_terminator(buf: &[u8], crlf: bool, nul: bool) -> Option<usize> {
    let t = if nul {
        memchr_byte(buf, b'\0')
    } else {
        memrchr_byte(buf, b'\n')
    };
    let t = t?;
    if crlf && t > 0 && buf[t - 1] == b'\r' {
        return Some(t + 1);
    }
    Some(t + 1)
}

fn find_terminator(buf: &[u8], crlf: bool, nul: bool) -> (Option<usize>, usize) {
    if nul {
        match memchr_byte(buf, b'\0') {
            Some(p) => (Some(p), 1),
            None => (None, 0),
        }
    } else {
        match memchr_byte(buf, b'\n') {
            Some(p) => {
                if crlf && p > 0 && buf[p - 1] == b'\r' {
                    (Some(p - 1), 2)
                } else {
                    (Some(p), 1)
                }
            }
            None => (None, 0),
        }
    }
}

pub fn memrchr_byte(buf: &[u8], needle: u8) -> Option<usize> {
    for i in (0..buf.len()).rev() {
        if buf[i] == needle {
            return Some(i);
        }
    }
    None
}
EOF
echo ok"}

