    pub path: Vec<u8>,
    pub number: u64,
    pub offset: u64,
    pub column: Option<u64>,
    pub bytes: Vec<u8>,
    /// The line as it appears in the input, including its terminator.
    pub line_text: Vec<u8>,
    pub submatches: Vec<(usize, usize)>,
    pub caps: Vec<Option<(usize, usize)>>,
    pub matched_text: Vec<u8>,
}

#[derive(Default, Clone, Copy)]
pub struct Stats {
    pub searches: u64,
    pub search_with_match: bool,
    pub bytes_searched: u64,
    pub matched_lines: u64,
    pub matches: u64,
}

pub trait Sink {
    fn match_line(&mut self, l: &Line);
    fn context_line(&mut self, l: &Line);
    fn binary(&mut self, offset: u64);
    fn end_file(&mut self, path: &[u8], had_match: bool, binary_offset: Option<u64>, st: &Stats);
}

pub struct Searcher<'a> {
    pub matcher: &'a crate::matcher::Matcher,
    pub crlf: bool,
    pub null_data: bool,
    pub max_count: u64,
    pub invert: bool,
    pub stop_on_nonmatch: bool,
    pub passthru: bool,
    pub before: u64,
    pub after: u64,
    pub text_mode: bool,
    pub only_matching: bool,
    pub column: bool,
    pub byte_offset: bool,
    pub multiline: bool,
    pub quiet: bool,
}

impl<'a> Searcher<'a> {
    pub fn new(m: &'a crate::matcher::Matcher) -> Searcher<'a> {
        Searcher {
            matcher: m,
            crlf: false,
            null_data: false,
            max_count: u64::MAX,
            invert: false,
            stop_on_nonmatch: false,
            passthru: false,
            before: 0,
            after: 0,
            text_mode: false,
            only_matching: false,
            column: false,
            byte_offset: false,
            multiline: false,
            quiet: false,
        }
    }

    fn find_in(&self, buf: &[u8]) -> Vec<crate::matcher::MMatch> {
        self.matcher.find_iter(buf)
    }

    pub fn search_reader(
        &self,
        path: &[u8],
        rdr: &mut dyn Read,
        sink: &mut dyn Sink,
        is_file: bool,
    ) -> Result<Stats, std::io::Error> {
        let mut st = Stats::default();
        st.searches = 1;
        let mut buf: Vec<u8> = Vec::with_capacity(WINDOW);
        let mut base: u64 = 0;
        let mut eof = false;
        let mut line_no: u64 = 0;
        let mut matched_lines: u64 = 0;
        let mut matches: u64 = 0;
        let mut pending: std::collections::VecDeque<Line> = std::collections::VecDeque::new();
        let mut after_remaining: u64 = 0;
        let mut binary_offset: Option<u64> = None;
        let mut suppressed = false;
        let mut first_window = true;
        let mut seen_match = false;
        let mut count: u64 = 0;
        let mut stopped = false;

        let term_nul = self.null_data;
        let crlf = self.crlf && !term_nul;

        while !stopped {
            if !eof {
                let want = if buf.len() < WINDOW {
                    WINDOW - buf.len()
                } else {
                    WINDOW
                };
                let mut chunk = vec![0u8; want];
                match rdr.read(&mut chunk) {
                    Ok(0) => eof = true,
                    Ok(n) => {
                        buf.extend_from_slice(&chunk[..n]);
                        if !eof && buf.len() < WINDOW {
                            continue;
                        }
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(e) => return Err(e),
                }
            }
            if first_window && !self.text_mode {
                first_window = false;
                if let Some(p) = memchr_byte(&buf, b'\0') {
                    binary_offset = Some(base + p as u64);
                    suppressed = true;
                    if !eof && buf.len() < WINDOW {
                        // keep filling so that the whole file is counted
                        continue;
                    }
                }
            }
            let end = match last_terminator(&buf, crlf, term_nul) {
                Some(e) => e,
                None => {
                    if eof {
                        buf.len()
                    } else {
                        continue;
                    }
                }
            };
            let region: Vec<u8> = buf[..end].to_vec();
            let region_len = end;
            // iterate over the lines in this region
            let mut pos = 0usize;
            while pos < region.len() {
                let (term_start, term_len) =
                    find_terminator(&region[pos..], crlf, term_nul);
                let (content, term_bytes) = match term_start {
                    Some(t) => (
                        &region[pos..pos + t],
                        region[pos + t..pos + t + term_len].to_vec(),
                    ),
                    None => (region[pos..], Vec::new()),
                };
                line_no += 1;
                let number = line_no;
                let offset = base + pos as u64;
                let mut line = Line {
                    path: path.to_vec(),
                    number,
                    offset,
                    column: None,
                    bytes: content.to_vec(),
                    line_text: {
                        let mut v = content.to_vec();
                        v.extend_from_slice(&term_bytes);
                        v
                    },
                    submatches: Vec::new(),
                    caps: Vec::new(),
                    matched_text: Vec::new(),
                };
                let found = self.find_in(&line.bytes);
                let is_match = if self.invert {
                    found.is_empty()
                } else {
                    !found.is_empty()
                };
                if is_match {
                    matched_lines += 1;
                }
                let has_line_match = if self.passthru {
                    !found.is_empty()
                } else {
                    is_match
                };
                // binary detection based on the line contents
                if has_line_match && !self.text_mode && binary_offset.is_none() && !suppressed {
                    if let Some(p) = memchr_byte(&line.bytes, b'\0') {
                        suppressed = true;
                        let off = offset + p as u64;
                        binary_offset = Some(off);
                        sink.binary(off);
                    }
                }
                if has_line_match {
                    seen_match = true;
                    matches += found.len() as u64;
                    if !suppressed {
                        for l in pending.drain(..) {
                            sink.context_line(&l);
                        }
                        self.emit_match(sink, &line, &found);
                        count += 1;
                    }
                    after_remaining = self.after;
                    if self.max_count > 0 && count >= self.max_count {
                        stopped = true;
                        break;
                    }
                } else {
                    if self.passthru {
                        if !suppressed {
                            sink.context_line(&line);
                        }
                    } else if after_remaining > 0 {
                        if !suppressed {
                            sink.context_line(&line);
                        }
                        after_remaining -= 1;
                    } else {
                        if self.stop_on_nonmatch && seen_match {
                            stopped = true;
                            break;
                        }
                        pending.push_back(line.clone());
                        while pending.len() > self.before as usize {
                            pending.pop_front();
                        }
                    }
                }
                let adv = content.len() + term_bytes.len();
                if adv == 0 {
                    break;
                }
                pos += adv;
                if term_bytes.is_empty() {
                    break;
                }
            }
            base += region_len as u64;
            buf.drain(..region_len);
            if eof && buf.is_empty() {
                break;
            }
            if eof && end == 0 && !region.is_empty() {
                break;
            }
        }
        st.matched_lines = matched_lines;
        st.matches = matches;
        st.search_with_match = matches > 0 || matched_lines > 0 || binary_offset.is_some();
        if let Some(b) = binary_offset {
            if !is_file {
                st.bytes_searched = base;
            } else {
                st.bytes_searched = b;
            }
        }
        sink.end_file(path, st.search_with_match, binary_offset, &st);
        Ok(st)
    }

    fn emit_match(&self, sink: &mut dyn Sink, m: &Line, found: &[crate::matcher::MMatch]) {
        if found.is_empty() {
            return;
        }
        if self.only_matching {
            for f in found {
                let l = Line {
                    path: m.path.clone(),
                    number: m.number,
                    offset: m.offset + f.start as u64,
                    column: Some(f.start as u64 + 1),
                    bytes: m.bytes[f.start..f.end].to_vec(),
                    line_text: m.line_text.clone(),
                    submatches: vec![(0, f.end - f.start)],
                    caps: f.caps.clone(),
                    matched_text: m.bytes[f.start..f.end].to_vec(),
                };
                sink.match_line(&l);
            }
            return;
        }
        let l = Line {
            path: m.path.clone(),
            number: m.number,
            offset: m.offset,
            column: if self.column {
                found.first().map(|f| f.start as u64 + 1)
            } else {
                None
            },
            bytes: m.bytes.clone(),
            line_text: m.line_text.clone(),
            submatches: found.iter().map(|f| (f.start, f.end)).collect(),
            caps: found.first().map(|f| f.caps.clone()).unwrap_or_default(),
            matched_text: found
                .first()
                .map(|f| m.bytes[f.start..f.end].to_vec())
                .unwrap_or_default(),
        };
        sink.match_line(&l);
    }
}

pub fn memchr_byte(buf: &[u8], needle: u8) -> Option<usize> {
    buf.iter().position(|&b| b == needle)
}

pub fn memrchr_byte(buf: &[u8], needle: u8) -> Option<usize> {
    for i in (0..buf.len()).rev() {
        if buf[i] == needle {
            return Some(i);
        }
    }
    None
}

/// Find the last complete line terminator in `buf`, returning the index one
/// past its end.
fn last_terminator(buf: &[u8], crlf: bool, nul: bool) -> Option<usize> {
    let t = if nul {
        memchr_byte(buf, b'\0')
    } else {
        memrchr_byte(buf, b'\n')
    }?;
    if crlf && t > 0 && buf[t - 1] == b'\r' {
        return Some(t + 1);
    }
    Some(t + 1)
}

fn find_terminator(buf: &[u8], crlf: bool, nul: bool) -> (Option<usize>, usize) {
    if nul {
        match memchr_byte(buf, b'\0') {
            Some(p) => (Some(p), 1),
            None => (None, 0),
        }
    } else {
        match memchr_byte(buf, b'\n') {
            Some(p) => {
                if crlf && p > 0 && buf[p - 1] == b'\r' {
                    (Some(p - 1), 2)
                } else {
                    (Some(p), 1)
                }
            }
            None => (None, 0),
        }
    }
}
EOF
echo ok"}

