fn has_literal_and_upper(pattern: &str) -> (bool, bool) {
    use regex_syntax::ast::{Ast, AstLiteral, ClassSetItem, ClassSetMember, LiteralKind, Span};
    fn lit_char(l: &AstLiteral) -> Option<char> {
        match l.kind {
            LiteralKind::Verbatim { .. } => Some(l.c),
            LiteralKind::Punctuation { c, .. } => Some(c),
            LiteralKind::Octal { c, .. } => Some(c),
            LiteralKind::HexFixed { c, .. } => Some(c),
            LiteralKind::HexBrace { c, .. } => Some(c),
            LiteralKind::Special(_) => None,
        }
    }
    fn walk(ast: &Ast, lit: &mut bool, upper: &mut bool) {
        match ast {
            Ast::Empty(_) => {}
            Ast::Flags(_) => {}
            Ast::Literal(l) => {
                if let Some(c) = lit_char(l) {
                    *lit = true;
                    if c.is_uppercase() {
                        *upper = true;
                    }
                }
            }
            Ast::Dot(_) => {}
            Ast::Assertion(_) => {}
            Ast::ClassUnicode(_) | Ast::ClassPerl(_) => {}
            Ast::ClassBracketed(cb) => {
                walk_set(&cb.kind, lit, upper);
            }
            Ast::Repetition(r) => walk(&r.ast, lit, upper),
            Ast::Group(g) => walk(&g.ast, lit, upper),
            Ast::Alternation(a) => {
                for a in &a.asts {
                    walk(a, lit, upper);
                }
            }
            Ast::Concat(c) => {
                for a in &c.asts {
                    walk(a, lit, upper);
                }
            }
        }
    }
    fn walk_range(
        lo: Option<char>,
        hi: Option<char>,
        lit: &mut bool,
        upper: &mut bool,
    ) {
        *lit = true;
        match (lo, hi) {
            (Some(l), Some(h)) => {
                if l <= 'Z' && h >= 'A' {
                    *upper = true;
                }
                if l.is_uppercase() || h.is_uppercase() {
                    *upper = true;
                }
            }
            _ => {}
        }
    }
    fn walk_set(set: &regex_syntax::ast::ClassSet, lit: &mut bool, upper: &mut bool) {
        match set {
            regex_syntax::ast::ClassSet::Item(item) => walk_member(item, lit, upper),
            regex_syntax::ast::ClassSet::BinaryOp(op) => {
                walk_set(&op.lhs, lit, upper);
                walk_set(&op.rhs, lit, upper);
            }
            regex_syntax::ast::ClassSet::Bracketed(cb) => walk_set(&cb.kind, lit, upper),
        }
    }
    fn walk_member(m: &ClassSetMember, lit: &mut bool, upper: &mut bool) {
        match m {
            ClassSetMember::Item(item) => match item {
                ClassSetItem::Literal(l) => {
                    *lit = true;
                    if l.c.is_uppercase() {
                        *upper = true;
                    }
                }
                ClassSetItem::Range(r) => {
                    walk_range(Some(r.start.c), Some(r.end.c), lit, upper);
                }
                _ => {}
            },
            ClassSetMember::Literal(l) => {
                *lit = true;
