        Ok(ast) => walk(&ast, &mut lit, &mut upper),
        Err(_) => return (true, true),
    }
    (lit, upper)
}

fn case_for(pattern: &str, mode: CaseMode) -> bool {
    match mode {
        CaseMode::Sensitive => false,
        CaseMode::Insensitive => true,
        CaseMode::Smart => {
            let (lit, upper) = has_literal_and_upper(pattern);
            lit && !upper
        }
    }
