pub struct Builder {
    pub patterns: Vec<String>,
    pub case: CaseMode,
    pub fixed: bool,
    pub word: bool,
    pub line: bool,
    pub crlf: bool,
    pub unicode: bool,
    pub multiline: bool,
    pub dotall: bool,
    pub size_limit: usize,
}

impl Builder {
    pub fn build(&self) -> Result<Matcher, String> {
        let mut singles = Vec::new();
        for p in &self.patterns {
            singles.push(self.one(p)?);
        }
        let combined_pattern = if singles.len() == 1 {
            // reuse the single regex to keep capture groups intact
            return Ok(Matcher {
                combined: singles[0].clone(),
                singles,
                multi: false,
            });
        } else {
            let mut parts: Vec<String> = Vec::new();
            for p in &self.patterns {
                parts.push(format!("(?:{})", self.wrap(p)?));
            }
            parts.join("|")
        };
        let combined = self.compile(&combined_pattern)?;
        Ok(Matcher {
            combined,
            singles,
            multi: self.patterns.len() > 1,
        })
    }

    fn wrap(&self, pattern: &str) -> Result<String, String> {
        let mut s = String::new();
        if self.crlf {
            s.push_str("(?R)");
        }
        if !self.unicode {
            s.push_str("(?-u)");
        }
        if self.dotall {
            s.push_str("(?s)");
        }
        s.push_str(pattern);
        if self.word {
            s = format!("\\b{{start-half}}{}\\b{{end-half}}", s);
        }
        if self.line {
            s = format!("^(?:{})$", s);
        }
        Ok(s)
    }

    fn one(&self, pattern: &str) -> Result<Regex, String> {
        let p = if self.fixed {
            regex::escape(pattern)
        } else {
            pattern.to_string()
        };
        let ci = case_for(&p, self.case);
        let mut s = String::new();
        if self.crlf {
            s.push_str("(?R)");
        }
        if !self.unicode {
            s.push_str("(?-u)");
        }
        if self.dotall {
            s.push_str("(?s)");
        }
        if ci {
            s.push_str("(?i)");
        } else {
            s.push_str("(?-i)");
        }
        s.push_str(&p);
        if self.word {
            s = format!("\\b{{start-half}}{}\\b{{end-half}}", s);
        }
        if self.line {
            s = format!("^(?:{})$", s);
        }
        self.compile(&s)
    }

    fn compile(&self, pat: &str) -> Result<Regex, String> {
        let mut b = RegexBuilder::new(pat);
        b.size_limit(self.size_limit);
        if !self.multiline {
            // no special setting needed: '.' never matches \n by default
        }
        match b.build() {
            Ok(r) => Ok(r),
            Err(e) => Err(format_error(&e)),
        }
    }
}

fn format_error(e: &regex::Error) -> String {
    match e {
        regex::Error::CompiledTooBig(limit) => {
            format!("compiled regex exceeds size limit of {}", limit)
        }
        _ => format!("{}", e),
    }
}

impl Matcher {
    pub fn find_iter(&self, buf: &[u8]) -> Vec<MMatch> {
        let text = unsafe { std::str::from_utf8_unchecked(buf) };
        let mut out = Vec::new();
        for m in self.combined.find_iter(text) {
            let caps = m.captures();
            let v: Vec<Option<(usize, usize)>> = caps
                .iter()
                .map(|c| c.map(|g| (g.start(), g.end())))
                .collect();
            if self.multi {
                // figure out which pattern matched
                let mut found = None;
                for (i, r) in self.singles.iter().enumerate() {
                    if let Some(mm) = r.captures_at(text, m.start()) {
                        if mm.start() == m.start() && mm.end() == m.end() {
                            found = Some(i);
                            break;
                        }
                    }
                }
                let idx = found.unwrap_or(0);
                if let Some(mm) = self.singles[idx].captures_at(text, m.start()) {
                    if mm.start() == m.start() && mm.end() == m.end() {
                        let c: Vec<Option<(usize, usize)>> = mm
                            .captures()
                            .iter()
                            .map(|g| g.map(|x| (x.start(), x.end())))
                            .collect();
                        out.push(MMatch {
                            start: m.start(),
                            end: m.end(),
                            caps: c,
                        });
                        continue;
                    }
                }
            }
            out.push(MMatch {
                start: m.start(),
                end: m.end(),
                caps: v,
            });
        }
        out
    }
}
