// Gitignore style rules and directory walking.
use std::collections::VecDeque;
use std::path::Path;

use crate::glob::{Glob, GlobError, GlobSet};

/// The different sources of ignore rules, ordered from highest to lowest
/// precedence.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Kind {
    RgIgnore,
    DotIgnore,
    GitIgnore,
    Exclude,
    Global,
    IgnoreFile,
}

pub struct RuleSet {
    /// globs with their origin
    pub rules: Vec<Rule>,
}

pub struct Rule {
    pub glob: Glob,
    pub kind: Kind,
    /// depth of the directory holding the ignore file (bigger = deeper)
    pub depth: i64,
    /// index used to keep the relative order of --ignore-file arguments
    pub seq: usize,
}

impl Default for RuleSet {
    fn default() -> Self {
        RuleSet { rules: Vec::new() }
    }
}

fn strip_trailing_ws(line: &str) -> &str {
    let b = line.as_bytes();
    let mut end = b.len();
    while end > 0 {
        let c = b[end - 1];
        if c == b' ' || c == b'\t' {
            // escaped trailing whitespace is kept
            let mut bs = 0;
            let mut i = end - 1;
            while i > 0 && b[i - 1] == b'\\' {
                bs += 1;
                i -= 1;
            }
            if bs % 2 == 1 {
                break;
            }
            end -= 1;
        } else {
            break;
        }
    }
    &line[..end]
}

impl RuleSet {
    /// Parse a gitignore formatted file. `path` is used in error messages.
    pub fn parse(text: &str, kind: Kind, depth: i64, seq: usize) -> (RuleSet, Vec<String>) {
        let mut rules = RuleSet::default();
        let mut errors = Vec::new();
        for (i, raw) in text.lines().enumerate() {
            let line = raw.strip_suffix('\r').unwrap_or(raw);
            let line = strip_trailing_ws(line);
            if line.is_empty() {
                continue;
            }
            let mut body = line;
            let mut bytes = body.as_bytes();
            if bytes[0] == b'\\' && bytes.len() > 1 && (bytes[1] == b'#' || bytes[1] == b'!') {
                // escaped comment or negation marker
            } else if bytes[0] == b'#' {
                continue;
            } else if bytes[0] == b'!' {
                body = &body[1..];
                bytes = body.as_bytes();
            }
            if bytes[0] == b'!' {
                // double negation is not supported by gitignore; treat as
                // a whitelist pattern with a literal !
            }
            let pat = body;
            if pat.is_empty() {
                continue;
            }
            match Glob::new(pat, false) {
                Ok(mut g) => {
                    g.negated = raw.starts_with('!');
                    rules.rules.push(Rule {
                        glob: g,
                        kind,
                        depth,
                        seq,
                    });
                }
                Err(GlobError(e)) => {
                    errors.push(format!(
                        "line {}: error parsing glob '{}': {}",
                        i + 1,
                        pat,
                        e
                    ));
                }
            }
        }
        (rules, errors)
    }

    /// Look for a match, honouring the precedence order.
    pub fn matched(&self, path: &str, is_dir: bool) -> Option<bool> {
        // Build the candidate list: kinds sorted by precedence, then depth
        // descending, then sequence descending.
        let mut idx: Vec<usize> = (0..self.rules.len()).collect();
        idx.sort_by(|a, b| {
            let ra = &self.rules[*a];
            let rb = &self.rules[*b];
            (ra.kind, std::cmp::Reverse(ra.depth), std::cmp::Reverse(ra.seq))
                .cmp(&(rb.kind, std::cmp::Reverse(rb.depth), std::cmp::Reverse(rb.seq)))
        });
        for i in idx {
            let r = &self.rules[i];
            if r.glob.matches(path, is_dir) {
                return Some(!r.glob.negated);
            }
        }
        None
    }
}

pub struct DirIgnores {
    pub depth: i64,
    pub path: String,
    pub set: RuleSet,
}

/// The walker: yields files that should be searched.
pub struct Walker {
    pub hidden: bool,
    pub follow: bool,
    pub max_depth: Option<u64>,
    pub ignore_dot: bool,
    pub ignore_vcs: bool,
    pub ignore_exclude: bool,
    pub ignore_global: bool,
    pub ignore_parent: bool,
    pub require_git: bool,
    pub one_file_system: bool,
    pub ignore_files: Vec<String>,
    pub no_ignore_files: bool,
    pub ignore_file_ci: bool,
    pub cwd_comps: Vec<String>,
    pub rules: RuleSet,
    pub messages: bool,
    pub debug: bool,
    pub dev_id: Option<u64>,
}

fn path_comps(p: &Path) -> Vec<String> {
    p.components()
        .map(|c| c.as_os_str().to_string_lossy().into_owned())
        .collect()
}

fn join_comps(comps: &[String]) -> String {
    comps.join("/")
}

impl Walker {
    pub fn new() -> Walker {
        let cwd = std::env::current_dir().unwrap_or_default();
        Walker {
            hidden: false,
            follow: false,
            max_depth: None,
            ignore_dot: false,
            ignore_vcs: false,
            ignore_exclude: false,
            ignore_global: false,
            ignore_parent: false,
            require_git: false,
            one_file_system: false,
            ignore_files: Vec::new(),
            no_ignore_files: false,
            ignore_file_ci: false,
            cwd_comps: path_comps(&cwd),
            rules: RuleSet::default(),
            messages: true,
            debug: false,
            dev_id: None,
        }
    }

    /// Load the ignore rules that apply to parents of the given root.
    fn load_parents(&mut self, root_abs_comps: &[String]) {
        if self.ignore_parent {
            return;
        }
        // ascend from the parent of the root up to the filesystem root
        let mut depth = root_abs_comps.len() as i64 - 1;
        let mut i = root_abs_comps.len() as i64 - 1;
        while i >= 0 {
            let dir_comps = &root_abs_comps[..i as usize];
            let dir = Path::new("/").join(join_comps(dir_comps));
            self.load_dir_rules(&dir, depth, true);
            depth -= 1;
            if i == 0 {
                break;
            }
            i -= 1;
        }
    }

    fn load_dir_rules(&mut self, dir: &Path, depth: i64, parent: bool) {
        // .rgignore
        if !self.ignore_dot {
            for name in [".rgignore"] {
                let p = dir.join(name);
                if let Ok(text) = std::fs::read_to_string(&p) {
                    let disp = display_path(&p);
                    let (set, errs) = RuleSet::parse(&text, Kind::RgIgnore, depth, 0);
                    for e in errs {
                        self.warn(&format!("{}: {}", disp, e));
                    }
                    self.rules.rules.extend(set.rules);
                }
            }
        }
        if !self.ignore_dot {
            let p = dir.join(".ignore");
            if let Ok(text) = std::fs::read_to_string(&p) {
                let disp = display_path(&p);
                let (set, errs) = RuleSet::parse(&text, Kind::DotIgnore, depth, 0);
                for e in errs {
                    self.warn(&format!("{}: {}", disp, e));
                }
                self.rules.rules.extend(set.rules);
            }
        }
        if !self.ignore_vcs {
            let is_git = dir.join(".git").exists();
            if self.require_git || is_git {
                let p = dir.join(".gitignore");
                if let Ok(text) = std::fs::read_to_string(&p) {
                    let disp = display_path(&p);
                    let (set, errs) = RuleSet::parse(&text, Kind::GitIgnore, depth, 0);
                    for e in errs {
                        self.warn(&format!("{}: {}", disp, e));
                    }
                    self.rules.rules.extend(set.rules);
                }
                if !self.ignore_exclude {
                    let p = dir.join(".git/info/exclude");
                    if let Ok(text) = std::fs::read_to_string(&p) {
                        let disp = display_path(&p);
                        let (set, errs) = RuleSet::parse(&text, Kind::Exclude, depth, 0);
                        for e in errs {
                            self.warn(&format!("{}: {}", disp, e));
                        }
                        self.rules.rules.extend(set.rules);
                    }
                }
            }
        }
        if !self.ignore_global && !self.ignore_vcs {
            // global git ignore file
            if let Some(p) = global_ignore_path() {
                if let Ok(text) = std::fs::read_to_string(&p) {
                    let (set, errs) = RuleSet::parse(&text, Kind::Global, i64::MIN, 0);
                    for e in errs {
                        self.warn(&format!("{}: {}", p.display(), e));
                    }
                    self.rules.rules.extend(set.rules);
                }
            }
        }
    }

    fn load_ignore_files(&mut self, depth: i64) {
        if self.no_ignore_files {
            return;
        }
        let n = self.ignore_files.len();
        for (i, f) in self.ignore_files.iter().enumerate() {
            if let Ok(text) = std::fs::read_to_string(f) {
                let (set, errs) = RuleSet::parse(&text, Kind::IgnoreFile, depth, i);
                for e in errs {
                    self.warn(&format!("{}: {}", f, e));
                }
                let _ = n;
                self.rules.rules.extend(set.rules);
            }
        }
    }

    fn warn(&self, msg: &str) {
        if self.messages {
            eprintln!("rg: {}", msg);
        }
    }

    pub fn walk<F: FnMut(Vec<u8>)>(&mut self, roots: &[String], mut f: F) {
        for root in roots {
            let p = Path::new(root);
            let abs_comps = {
                let mut c = self.cwd_comps.clone();
                let rc = path_comps(p);
                for comp in rc {
                    if comp == "." {
                        continue;
                    }
                    if comp == ".." {
                        c.pop();
                        continue;
                    }
                    c.push(comp);
                }
                c
            };
            if !self.ignore_parent {
                self.load_parents(&abs_comps);
            }
            let depth = abs_comps.len() as i64;
            self.load_dir_rules(Path::new("/").join(join_comps(&abs_comps)), depth, false);
            self.load_ignore_files(depth);
            let mut stack: Vec<Vec<String>> = Vec::new();
            self.recurse(
                Path::new("/").join(join_comps(&abs_comps)),
                &abs_comps,
                root,
                depth,
                &mut stack,
                &mut f,
            );
        }
    }

    fn recurse<F: FnMut(Vec<u8>)>(
        &mut self,
        dir: std::path::PathBuf,
        dir_comps: &[String],
        _root_disp: &str,
        depth: i64,
        _stack: &mut Vec<Vec<String>>,
        f: &mut F,
    ) {
        let rd = match std::fs::read_dir(&dir) {
            Ok(rd) => rd,
            Err(_) => return,
        };
        let mut entries: Vec<_> = rd.flatten().collect();
        entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));
        for e in entries {
            let name = e.file_name().to_string_lossy().into_owned();
            let ft = match e.file_type() {
                Ok(ft) => ft,
                Err(_) => continue,
            };
            let is_link = ft.is_symlink();
            let is_dir = if is_link {
                if !self.follow {
                    continue;
                }
                match std::fs::metadata(e.path()) {
                    Ok(m) => m.is_dir(),
                    Err(_) => {
                        self.warn(&format!(
                            "{}: No such file or directory (os error 2)",
                            rel_display(dir_comps, &name, self.cwd_comps.len())
                        ));
                        continue;
                    }
                }
            } else {
                ft.is_dir()
            };
            if !self.hidden && name.starts_with('.') {
                continue;
            }
            let rel = rel_display(dir_comps, &name, self.cwd_comps.len());
            let m = self.rules.matched(&rel, is_dir);
            if m == Some(false) {
                continue;
            }
            if is_dir {
                if let Some(md) = self.max_depth {
                    let d = depth - self.cwd_comps.len() as i64;
                    if d + 1 > md as i64 {
                        continue;
                    }
                }
                let mut nc = dir_comps.to_vec();
                nc.push(name.clone());
                let child = std::path::Path::new("/").join(join_comps(&nc));
                self.load_dir_rules(&child, (nc.len()) as i64, false);
                self.recurse(child, &nc, _root_disp, depth + 1, _stack, f);
            } else {
                f(rel.into_bytes());
            }
        }
    }
}

fn rel_display(dir_comps: &[String], name: &str, cwd_len: usize) -> String {
    let mut v: Vec<&str> = Vec::new();
    for c in &dir_comps[cwd_len..] {
        v.push(c);
    }
    v.push(name);
    v.join("/")
}

fn display_path(p: &Path) -> String {
