                        continue;
                    }
                }
            } else {
                ft.is_dir()
            };
            if !self.hidden && name.starts_with('.') {
                continue;
            }
            let rel = rel_display(dir_comps, &name, self.cwd_comps.len());
            let m = self.rules.matched(&rel, is_dir);
            if m == Some(false) {
                continue;
            }
            if is_dir {
                if let Some(md) = self.max_depth {
                    let d = depth - self.cwd_comps.len() as i64;
                    if d + 1 > md as i64 {
                        continue;
                    }
