    }
}

pub struct Walker {
    pub hidden: bool,
    pub follow: bool,
    pub max_depth: Option<u64>,
    pub ignore_dot: bool,
    pub ignore_vcs: bool,
    pub ignore_exclude: bool,
    pub ignore_global: bool,
    pub ignore_parent: bool,
    pub no_require_git: bool,
    pub one_file_system: bool,
    pub ignore_files: Vec<String>,
    pub no_ignore_files: bool,
    pub ignore_file_ci: bool,
    pub cwd_comps: Vec<String>,
    pub rules: RuleSet,
    pub quiet: bool,
    pub messages: bool,
    pub errors: Vec<String>,
    /// The root as written by the user (empty when no path was given).
    pub root_disp: String,
    /// Path used for the internally reported errors.
    pub root_internal: String,
    /// Root components relative to the cwd.
    pub root_comps: Vec<String>,
    pub dev_root: Option<u64>,
    pub saw_loop: bool,
}

fn comps_of(p: &Path) -> Vec<String> {
    p.components()
        .map(|c| c.as_os_str().to_string_lossy().into_owned())
        .collect()
}

impl Walker {
    pub fn new() -> Walker {
        let cwd = std::env::current_dir().unwrap_or_default();
        Walker {
            hidden: false,
            follow: false,
            max_depth: None,
            ignore_dot: false,
            ignore_vcs: false,
            ignore_exclude: false,
            ignore_global: false,
            ignore_parent: false,
            no_require_git: false,
            one_file_system: false,
            ignore_files: Vec::new(),
            no_ignore_files: false,
            ignore_file_ci: false,
            cwd_comps: comps_of(&cwd),
            rules: RuleSet::default(),
            quiet: false,
            messages: true,
            errors: Vec::new(),
            root_disp: String::new(),
            root_internal: String::new(),
            root_comps: Vec::new(),
            dev_root: None,
            saw_loop: false,
        }
    }

    fn warn(&mut self, msg: String) {
        if self.messages {
            eprintln!("rg: {}", msg);
        }
    }

    fn load_dir_rules(&mut self, comps: &[String], depth: usize, internal: &str) {
        let base = comps.len();
        let mut load = |name: &str, kind: Kind, s: &mut Self| {
            let mut path = std::path::PathBuf::from("/");
            for c in comps {
                path.push(c);
            }
            path.push(name);
            match std::fs::read_to_string(&path) {
                Ok(text) => {
                    let (set, errs) = RuleSet::parse(&text, kind, base, 0, s.ignore_file_ci);
                    for e in errs {
                        s.warn(format!("{}: {}", internal, e));
                    }
                    s.rules.rules.extend(set.rules);
                }
                Err(_) => {}
            }
        };
        if !self.ignore_dot {
            load(".rgignore", Kind::RgIgnore, self);
            load(".ignore", Kind::DotIgnore, self);
        }
        if !self.ignore_vcs {
            let mut p = std::path::PathBuf::from("/");
            for c in comps {
                p.push(c);
            }
            let is_git = p.join(".git").exists();
            if !self.no_require_git || is_git {
                load(".gitignore", Kind::GitIgnore, self);
                if !self.ignore_exclude {
                    let mut ep = p.clone();
                    ep.push(".git/info/exclude");
                    if let Ok(text) = std::fs::read_to_string(&ep) {
                        let (set, errs) =
                            RuleSet::parse(&text, Kind::Exclude, base, 0, self.ignore_file_ci);
                        for e in errs {
                            self.warn(format!("{}: {}", internal, e));
                        }
                        self.rules.rules.extend(set.rules);
                    }
                }
            }
            if !self.ignore_global {
                if let Some(gp) = global_ignore_path() {
                    if let Ok(text) = std::fs::read_to_string(&gp) {
                        let (set, errs) = RuleSet::parse(
                            &text,
                            Kind::Global,
                            self.cwd_comps.len(),
                            0,
                            self.ignore_file_ci,
                        );
                        for e in errs {
                            self.warn(format!("{}: {}", gp.display(), e));
                        }
                        self.rules.rules.extend(set.rules);
                    }
                }
            }
        }
    }

    pub fn walk<F: FnMut(Vec<u8>)>(&mut self, roots: &[String], f: &mut F) {
        if !self.no_ignore_files {
            for (i, fl) in self.ignore_files.iter().enumerate() {
                match std::fs::read_to_string(fl) {
                    Ok(text) => {
                        let (set, errs) = RuleSet::parse(
                            &text,
                            Kind::IgnoreFile,
                            self.cwd_comps.len(),
                            i,
                            self.ignore_file_ci,
                        );
                        for e in errs {
                            self.warn(format!("{}: {}", fl, e));
                        }
                        self.rules.rules.extend(set.rules);
                    }
                    Err(e) => {
                        self.warn(format!("{}: {}", fl, crate::util::os_err(&e)));
                        self.errors.push(format!("{}: {}", fl, crate::util::os_err(&e)));
                    }
                }
            }
        }
        for root in roots {
            let given = Path::new(root);
            self.root_disp = root.clone();
            self.root_internal = root.clone();
            let mut root_comps: Vec<String> = Vec::new();
            for c in comps_of(given) {
                if c == "." {
                    continue;
                }
                if c == ".." {
                    root_comps.pop();
                    continue;
                }
                root_comps.push(c);
            }
            self.root_comps = root_comps.clone();
            let mut abs: Vec<String> = self.cwd_comps.clone();
            abs.extend(root_comps.iter().cloned());
            let depth0 = abs.len();
            if !self.ignore_parent {
                // load rules from parents, deepest first
                let mut d = depth0;
                while d > 0 {
                    d -= 1;
                    let prefix = &abs[..d];
                    let internal = format!("/{}", prefix.join("/"));
                    self.load_dir_rules(prefix, d, &internal);
                }
            }
            self.load_dir_rules(&abs, depth0, &format!("/{}", abs.join("/")));
            self.dev_root = if self.one_file_system {
                std::fs::metadata(Path::new("/").join(abs.join("/")))
                    .ok()
                    .map(|m| m.dev())
            } else {
                None
            };
            self.recurse(&abs, depth0, 0, f);
        }
    }

    fn recurse<F: FnMut(Vec<u8>)>(
        &mut self,
        dir_comps: &[String],
        depth: usize,
        level: u64,
        f: &mut F,
    ) {
        let dir = Path::new("/").join(dir_comps.join("/"));
        let rd = match std::fs::read_dir(&dir) {
            Ok(rd) => rd,
            Err(e) => {
                if level > 0 {
                    let internal = self.internal_path(dir_comps, "");
                    self.warn(format!("{}: {}", internal, crate::util::os_err(&e)));
                }
                return;
            }
        };
        for entry in rd {
            let ent = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            let name = ent.file_name().to_string_lossy().into_owned();
            let ft = match ent.file_type() {
                Ok(ft) => ft,
                Err(_) => continue,
            };
            let is_link = ft.is_symlink();
            let mut is_dir = ft.is_dir();
            if is_link {
                if !self.follow {
                    continue;
                }
                match std::fs::metadata(ent.path()) {
                    Ok(m) => is_dir = m.is_dir(),
                    Err(e) => {
                        let internal = self.internal_path(dir_comps, &name);
                        self.warn(format!("{}: {}", internal, crate::util::os_err(&e)));
                        continue;
                    }
                }
            }
            let mut comps = dir_comps.to_vec();
            comps.push(name.clone());
            if !self.hidden && name.starts_with('.') {
                continue;
            }
            let m = self.rules.matched(&comps, is_dir);
            if m == Some(false) {
                continue;
            }
            if self.one_file_system {
                if let Some(root_dev) = self.dev_root {
                    if let Ok(md) = std::fs::metadata(ent.path()) {
                        if md.dev() != root_dev {
                            continue;
                        }
                    }
                }
            }
            if is_dir {
                if let Some(md) = self.max_depth {
                    if level >= md {
                        continue;
                    }
                }
                // symlink loop detection
                if self.follow {
                    if let Ok(canon) = std::fs::canonicalize(&ent.path()) {
                        let ccomps = comps_of(&canon);
                        if ccomps.len() < comps.len()
                            && ccomps == comps[..ccomps.len()]
                        {
                            let internal = self.internal_path(&comps, "");
                            self.warn(format!(
                                "File system loop found: {} points to an ancestor {}",
                                internal,
                                format!("/{}", ccomps.join("/"))
                            ));
                            continue;
                        }
                    }
                }
                let internal_dir = self.internal_path(&comps, "");
                self.load_dir_rules(&comps, comps.len(), &internal_dir);
                self.recurse(&comps, depth, level + 1, f);
            } else {
                f(self.display_path(&comps).into_bytes());
            }
        }
    }

    fn internal_path(&self, comps: &[String], name: &str) -> String {
        let rel = &comps[self.cwd_comps.len()..];
        let mut s = self.root_internal.clone();
        if !s.is_empty() && !s.ends_with('/') {
            s.push('/');
        }
        s.push_str(&rel.join("/"));
        if !name.is_empty() {
            if !s.is_empty() && !s.ends_with('/') {
                s.push('/');
            }
            s.push_str(name);
        }
        s
    }

    fn display_path(&self, comps: &[String]) -> String {
        let rel = &comps[self.cwd_comps.len()..];
        let mut s = self.root_disp.clone();
        if !s.is_empty() && !s.ends_with('/') {
            s.push('/');
        }
        s.push_str(&rel.join("/"));
        if s == "./" {
            s = String::new();
        }
        s
    }
}

fn global_ignore_path() -> Option<std::path::PathBuf> {
    if let Ok(v) = std::env::var("GIT_CONFIG") {
        let p = std::path::PathBuf::from(v);
        if p.is_file() {
            return Some(p);
        }
    }
    if let Ok(h) = std::env::var("HOME") {
        let p = std::path::PathBuf::from(h).join(".config/git/ignore");
        if p.exists() {
            return Some(p);
        }
        let p = std::path::PathBuf::from(h).join(".config/git/excludes");
        if p.exists() {
            return Some(p);
        }
    }
    None
}
