use std::path::Path;

use crate::glob::{Glob, GlobError};

/// Sources of ignore rules, ordered from highest to lowest precedence.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Kind {
    RgIgnore,
    DotIgnore,
    GitIgnore,
    Exclude,
    Global,
    IgnoreFile,
}

pub struct Rule {
    pub glob: Glob,
    pub kind: Kind,
    /// Absolute depth (number of path components) of the directory the rules
    /// are relative to.
    pub base: usize,
    /// Used to order several --ignore-file arguments.
    pub seq: usize,
}

#[derive(Default)]
pub struct RuleSet {
    pub rules: Vec<Rule>,
}

fn strip_trailing_ws(line: &str) -> &str {
    let b = line.as_bytes();
    let mut end = b.len();
    while end > 0 {
        let c = b[end - 1];
        if c == b' ' || c == b'\t' {
            let mut bs = 0;
            let mut i = end - 1;
            while i > 0 && b[i - 1] == b'\\' {
                bs += 1;
                i -= 1;
            }
            if bs % 2 == 1 {
                break;
            }
            end -= 1;
        } else {
            break;
        }
    }
    &line[..end]
}

impl RuleSet {
    pub fn parse(
        text: &str,
        kind: Kind,
        base: usize,
        seq: usize,
        ci: bool,
    ) -> (RuleSet, Vec<String>) {
        let mut rules = RuleSet::default();
        let mut errors = Vec::new();
        for (i, raw) in text.lines().enumerate() {
            let line = raw.strip_suffix('\r').unwrap_or(raw);
            let line = strip_trailing_ws(line);
            if line.is_empty() {
                continue;
            }
            let bytes = line.as_bytes();
            if bytes[0] == b'#' {
                continue;
            }
            let mut negated = false;
            let mut body = line;
            if bytes[0] == b'!' {
                if bytes.len() > 1 && bytes[1] == b'\\' {
                    // escaped negation marker
                } else {
                    negated = true;
                    body = &body[1..];
                }
            }
            if body.is_empty() {
                continue;
            }
            match Glob::new(body, ci) {
                Ok(mut g) => {
                    g.negated = negated;
                    rules.rules.push(Rule {
                        glob: g,
                        kind,
                        base,
                        seq,
                    });
                }
                Err(GlobError(e)) => {
                    errors.push(format!("line {}: error parsing glob '{}': {}", i + 1, body, e));
                }
            }
        }
        (rules, errors)
    }

    pub fn matched(&self, comps: &[String], is_dir: bool) -> Option<bool> {
        let mut idx: Vec<usize> = (0..self.rules.len()).collect();
        idx.sort_by(|a, b| {
            let ra = &self.rules[*a];
            let rb = &self.rules[*b];
            (ra.kind, std::cmp::Reverse(ra.base), std::cmp::Reverse(ra.seq)).cmp(&(
                rb.kind,
                std::cmp::Reverse(rb.base),
                std::cmp::Reverse(rb.seq),
            ))
        });
        for i in idx {
            let r = &self.rules[i];
            if r.base > comps.len() {
                continue;
            }
            let rel = comps[r.base..].join("/");
            if r.glob.matches(&rel, is_dir) {
                return Some(!r.glob.negated);
            }
        }
        None
    }
}

