// File type definitions (populated from the bundled type table).
use std::collections::{HashMap, HashSet};

use crate::glob::{Glob, GlobError};

pub struct Types {
    pub names: Vec<String>,
    pub globs: HashMap<String, Vec<Glob>>,
    pub selected: HashSet<String>,
    pub not_selected: HashSet<String>,
    pub whitelist: bool,
}

impl Types {
    pub fn new(table: &str) -> Types {
        let mut names = Vec::new();
        let mut globs: HashMap<String, Vec<Glob>> = HashMap::new();
        for line in table.lines() {
            if line.is_empty() {
                continue;
            }
            let mut it = line.splitn(2, ": ");
            let name = match it.next() {
                Some(n) => n.to_string(),
                None => continue,
            };
            let rest = it.next().unwrap_or("");
            let mut v = Vec::new();
            for g in rest.split(", ") {
                if g.is_empty() {
                    continue;
                }
                match Glob::new(g, false) {
                    Ok(gg) => v.push(gg),
                    Err(_) => {}
                }
            }
            if !names.contains(&name) {
                names.push(name);
            }
