    pub fn clear(&mut self, name: &str) {
        self.globs.insert(name.to_string(), Vec::new());
    }

    pub fn select(&mut self, name: &str) {
        if name == "all" {
            let all: HashSet<String> = self.names.iter().cloned().collect();
            self.selected = all;
            self.whitelist = true;
            return;
        }
        if !self.globs.contains_key(name) {
