// Expansion of -r/--replace replacement strings.
pub fn expand(rep: &[u8], caps: &[Option<(usize, usize)>], text: &[u8], _styled: bool) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0usize;
    while i < rep.len() {
        let c = rep[i];
        if c != b'$' {
            out.push(c);
            i += 1;
            continue;
        }
        if i + 1 >= rep.len() {
            out.push(b'$');
            i += 1;
            continue;
        }
        if rep[i + 1] == b'$' {
            out.push(b'$');
            i += 2;
            continue;
        }
        if rep[i + 1] == b'{' {
            // find the closing brace
            let mut j = i + 2;
            while j < rep.len() && rep[j] != b'}' {
                j += 1;
            }
            if j >= rep.len() {
                // no closing brace: literal
                out.push(b'$');
                i += 1;
                continue;
            }
            let name = &rep[i + 2..j];
            let g = lookup(name, caps, text);
            out.extend_from_slice(g);
            i = j + 1;
            continue;
        }
        // longest run of [_0-9A-Za-z]
        let mut j = i + 1;
        while j < rep.len() {
            let c = rep[j];
            if c.is_ascii_alphanumeric() || c == b'_' {
                j += 1;
            } else {
                break;
            }
        }
        if j == i + 1 {
            out.push(b'$');
            i += 1;
            continue;
        }
        let name = &rep[i + 1..j];
        let g = lookup(name, caps, text);
        out.extend_from_slice(g);
        i = j;
    }
    out
}

fn lookup(name: &[u8], caps: &[Option<(usize, usize)>], text: &[u8]) -> &[u8] {
    // numeric group?
    let is_num = !name.is_empty() && name.iter().all(|b| b.is_ascii_digit());
    if is_num {
        if let Ok(idx) = std::str::from_utf8(name).unwrap().parse::<usize>() {
            if idx < caps.len() {
                if let Some((s, e)) = caps[idx] {
                    if s <= e && e <= text.len() {
                        return &text[s..e];
                    }
                }
            }
        }
        return b"";
    }
    b""
}
