pub fn os_err(e: &std::io::Error) -> String {
    let msg = match e.raw_os_error() {
        Some(code) => format!("{} (os error {})", strerror(code), code),
        None => format!("{}", e),
    };
    msg
}

pub fn strerror(code: i32) -> String {
    // minimal errno table for the messages ripgrep prints
    let s = match code {
        1 => "Operation not permitted",
        2 => "No such file or directory",
        5 => "Input/output error",
        9 => "Bad file descriptor",
        13 => "Permission denied",
        20 => "Not a directory",
        21 => "Is a directory",
        24 => "Too many open files",
        36 => "File name too long",
        40 => "Too many levels of symbolic links",
        75 => "Value too large for defined data type",
        _ => return format!("Unknown error {}", code),
    };
    s.to_string()
}

const TBL: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

pub fn b64encode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity((input.len() + 2) / 3 * 4);
    for chunk in input.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(TBL[((n >> 18) & 63) as usize]);
        out.push(TBL[((n >> 12) & 63) as usize]);
        if chunk.len() > 1 {
            out.push(TBL[((n >> 6) & 63) as usize]);
        } else {
            out.push(b'=');
        }
        if chunk.len() > 2 {
            out.push(TBL[(n & 63) as usize]);
        } else {
            out.push(b'=');
        }
    }
    out
}
