impl ArgErr {
    pub fn message(&self) -> String {
        match self {
            ArgErr::Unrecognized(s) => format!("unrecognized flag {}", s),
            ArgErr::MissingValue(d, inner) => {
                format!("missing value for flag {}: {}", d, inner)
            }
            ArgErr::FlagParse(d, inner) => format!("error parsing flag {}: {}", d, inner),
            ArgErr::InvalidCli(inner) => format!("invalid CLI arguments: {}", inner),
