fn parse_num(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("value is not a valid number: cannot parse integer from empty string".into());
    }
    let b = s.as_bytes();
    let mut i = 0;
    if b[0] == b'+' {
        i = 1;
    } else if b[0] == b'-' {
        return Err("value is not a valid number: invalid digit found in string".into());
    }
    if i >= b.len() {
        return Err("value is not a valid number: cannot parse integer from empty string".into());
    }
    let mut v: u64 = 0;
    let mut overflow = false;
    for &c in &b[i..] {
        if !c.is_ascii_digit() {
            return Err("value is not a valid number: invalid digit found in string".into());
        }
        let d = (c - b'0') as u64;
        match v.checked_mul(10).and_then(|x| x.checked_add(d)) {
            Some(x) => v = x,
            None => overflow = true,
        }
    }
    if overflow {
        return Err("value is not a valid number: number too large to fit in target type".into());
    }
    Ok(v)
}

fn parse_size(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err(format!(
            "invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix",
            s
        ));
    }
    let (num, suffix) = match s.chars().last() {
        Some('K') => (&s[..s.len() - 1], 1024u64),
        Some('M') => (&s[..s.len() - 1], 1024 * 1024),
        Some('G') => (&s[..s.len() - 1], 1024 * 1024 * 1024),
        _ => (s, 1),
    };
    let v = match parse_num(num) {
        Ok(v) => v,
        Err(_) => {
            return Err(format!(
                "invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix",
                s
            ))
        }
    };
    match v.checked_mul(suffix) {
        Some(x) => Ok(x),
        None => Err(format!(
            "invalid size: invalid format for size '{}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix",
            s
        )),
    }
}

pub fn parse(args: &[String], s: &mut Settings) -> Result<(), ArgErr> {
    let mut i = 0usize;
    let mut positional_only = false;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if positional_only {
            s.push_positional(arg.clone());
            continue;
        }
        if arg == "--" {
            positional_only = true;
            continue;
        }
        if arg.starts_with("--") {
            let body = &arg[2..];
            let (name, val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let (is_positive, name) = match lookup_long(name) {
                Some((idx, _)) => (true, (idx, name.to_string())),
                None => {
                    // try the positive spelling
                    match POSITIVES.iter().find(|p| format!("no-{}", p) == name) {
                        Some(p) => {
                            let full = p.to_string();
                            (false, (lookup_long(&full).unwrap().0, full))
                        }
                        None => {
                            return Err(ArgErr::Unrecognized(format!("--{}", name)));
                        }
                    }
                }
            };
            let (idx, _) = name;
            let def = &FLAGS[idx];
            let disp = format!("--{}", def.name);
            if def.kind == FlagKind::Value {
                let v = match val {
                    Some(v) => v,
                    None => {
                        if i < args.len() {
                            let v = args[i].clone();
                            i += 1;
                            v
                        } else {
                            return Err(ArgErr::MissingValue(
                                disp.clone(),
                                format!("missing argument for option '{}'", disp),
                            ));
                        }
                    }
                };
                apply(s, &disp, &def.name, !is_positive, &v)?;
            } else {
                if let Some(v) = val {
                    return Err(ArgErr::InvalidCli(format!(
                        "unexpected argument for option '{}': \"{}\"",
                        disp,
                        v
                    )));
                }
                apply(s, &disp, &def.name, !is_positive, "")?;
            }
            continue;
        }
        if arg.len() > 1 && arg.starts_with('-') {
            let chars: Vec<char> = arg.chars().collect();
            let mut k = 1usize;
            while k < chars.len() {
                let c = chars[k];
                let (idx, def) = match lookup_short(c) {
                    Some(x) => x,
                    None => {
                        return Err(ArgErr::Unrecognized(format!("-{}", c)));
                    }
                };
                let disp = format!("-{}", c);
                if def.kind == FlagKind::Value {
                    let rest: String = chars[k + 1..].iter().collect();
                    let v = if rest.is_empty() {
                        if i < args.len() {
                            let v = args[i].clone();
                            i += 1;
                            v
                        } else {
                            return Err(ArgErr::MissingValue(
                                disp.clone(),
                                format!("missing argument for option '{}'", disp),
                            ));
                        }
                    } else if let Some(stripped) = rest.strip_prefix('=') {
                        stripped.to_string()
                    } else {
                        rest
                    };
                    apply(s, &disp, &def.name, false, &v)?;
                    break;
                } else {
                    let rest: String = chars[k + 1..].iter().collect();
                    if let Some(stripped) = rest.strip_prefix('=') {
                        if !stripped.is_empty() {
                            return Err(ArgErr::InvalidCli(format!(
                                "unexpected argument for option '{}': \"{}\"",
                                disp,
                                stripped
                            )));
                        }
                        if !rest.is_empty() {
                            break;
                        }
                    }
                    apply(s, &disp, &def.name, false, "")?;
                    k += 1;
                    continue;
                }
            }
            continue;
        }
        s.push_positional(arg.clone());
    }
    Ok(())
}

impl Settings {
    fn push_positional(&mut self, a: String) {
        if !self.pattern_given {
            self.patterns.push(a);
            self.pattern_given = true;
        } else {
            self.paths.push(a);
        }
    }
}

fn choice(v: &str, opts: &[&str]) -> Result<(), String> {
    if opts.contains(&v) {
        Ok(())
    } else {
        Err(format!("choice '{}' is unrecognized", v))
    }
}

fn apply(
    s: &mut Settings,
    disp: &str,
    name: &str,
    negated: bool,
    value: &str,
) -> Result<(), ArgErr> {
    let pe = |m: String| ArgErr::FlagParse(disp.to_string(), m);
    macro_rules! num {
        ($field:ident) => {{
            match parse_num(value) {
                Ok(v) => s.$field = Some(v),
                Err(e) => return Err(pe(e)),
            }
        }};
    }
    match name {
        "regexp" => {
            s.patterns.push(value.to_string());
            s.pattern_given = true;
        }
        "file" => {
            s.pattern_files.push(value.to_string());
            s.pattern_given = true;
        }
        "pre" => {
            s.pre = Some(value.to_string());
        }
        "pre-glob" => {
            s.pre_glob.push(value.to_string());
        }
        "search-zip" => s.search_zip = !negated,
        "case-sensitive" => s.case = Some(CaseMode::Sensitive),
        "ignore-case" => s.case = Some(CaseMode::Insensitive),
        "smart-case" => s.case = Some(CaseMode::Smart),
        "crlf" => s.crlf = Some(!negated),
        "dfa-size-limit" => match parse_size(value) {
            Ok(_) => s.dfa_size_limit = Some(value.to_string()),
            Err(e) => return Err(pe(e)),
        },
        "encoding" => {
            if value == "auto" || value == "none" || crate::encoding::known(value) {
                s.encoding = Some(value.to_string());
            } else {
                return Err(pe(format!("grep config error: unknown encoding: {}", value)));
            }
        }
        "engine" => {
            match value {
                "default" | "pcre2" | "auto" => s.engine = Some(value.to_string()),
                _ => {
                    return Err(pe(format!(
                        "unrecognized regex engine '{}'",
                        value
                    )))
                }
            }
        }
        "fixed-strings" => s.fixed = Some(!negated),
        "invert-match" => s.invert = Some(!negated),
        "line-regexp" => s.line_regexp = Some(!negated),
        "max-count" => num!(max_count),
        "mmap" => s.mmap = Some(!negated),
        "multiline" => s.multiline = Some(!negated),
        "multiline-dotall" => s.multiline_dotall = Some(!negated),
        "no-unicode" => s.unicode = Some(false),
        "unicode" => s.unicode = Some(true),
        "null-data" => s.null_data = Some(true),
        "pcre2" => s.pcre2 = Some(!negated),
        "regex-size-limit" => match parse_size(value) {
            Ok(_) => s.regex_size_limit = Some(value.to_string()),
            Err(e) => return Err(pe(e)),
        },
        "stop-on-nonmatch" => s.stop_on_nonmatch = Some(!negated),
        "text" => s.text = Some(!negated),
        "binary" => s.binary = Some(!negated),
        "threads" => num!(threads),
        "word-regexp" => s.word = Some(!negated),
        "auto-hybrid-regex" => s.auto_hybrid = Some(!negated),
        "no-pcre2-unicode" => s.pcre2_unicode = Some(false),
        "pcre2-unicode" => s.pcre2_unicode = Some(true),
        "binary" => {}
        "follow" => s.hidden = None,
        "glob" => s.globs.push(value.to_string()),
        "iglob" => s.iglobs.push(value.to_string()),
        "glob-case-insensitive" => s.glob_ci = Some(!negated),
        "hidden" => s.hidden = Some(!negated),
        "ignore-file" => s.ignore_files.push(value.to_string()),
        "ignore-file-case-insensitive" => s.ignore_file_ci = Some(!negated),
        "max-depth" => num!(max_depth),
        "max-filesize" => match parse_size(value) {
            Ok(_) => s.max_filesize = Some(value.to_string()),
            Err(e) => return Err(pe(e)),
        },
        "no-ignore" => s.no_ignore = Some(!negated),
        "ignore" => s.no_ignore = Some(false),
        "no-ignore-dot" => s.no_ignore_dot = Some(!negated),
        "ignore-dot" => s.no_ignore_dot = Some(false),
        "no-ignore-exclude" => s.no_ignore_exclude = Some(!negated),
        "ignore-exclude" => s.no_ignore_exclude = Some(false),
        "no-ignore-files" => s.no_ignore_files = Some(!negated),
        "ignore-files" => s.no_ignore_files = Some(false),
        "no-ignore-global" => s.no_ignore_global = Some(!negated),
        "ignore-global" => s.no_ignore_global = Some(false),
        "no-ignore-parent" => s.no_ignore_parent = Some(!negated),
        "ignore-parent" => s.no_ignore_parent = Some(false),
        "no-ignore-vcs" => s.no_ignore_vcs = Some(!negated),
        "ignore-vcs" => s.no_ignore_vcs = Some(false),
        "no-require-git" => s.no_require_git = Some(true),
        "require-git" => s.no_require_git = Some(false),
        "one-file-system" => s.one_file_system = Some(!negated),
        "type" => s.type_sel.push(value.to_string()),
        "type-not" => s.type_not.push(value.to_string()),
        "type-add" => s.type_add.push(value.to_string()),
        "type-clear" => s.type_clear.push(value.to_string()),
        "unrestricted" => {
            if !negated {
                s.unrestricted += 1;
            }
        }
        "after-context" => num!(after),
        "before-context" => num!(before),
        "block-buffered" => s.block_buffered = Some(!negated),
        "byte-offset" => s.byte_offset = Some(!negated),
        "color" => match value {
            "never" | "auto" | "always" | "ansi" => s.color = Some(value.to_string()),
            _ => return Err(pe(format!("choice '{}' is unrecognized", value))),
        },
        "colors" => {
            crate::text::parse_spec(value, &mut crate::colors()).map_err(pe)?
        }
        "column" => s.column = Some(!negated),
        "context" => num!(context),
        "context-separator" => s.context_sep = Some(value.to_string()),
        "field-context-separator" => s.field_context_sep = Some(value.to_string()),
        "field-match-separator" => s.field_match_sep = Some(value.to_string()),
        "heading" => s.heading = Some(!negated),
        "hostname-bin" => s.hostname_bin = Some(value.to_string()),
        "hyperlink-format" => {
            let fmt = match crate::hyper::alias_format(value) {
                Some(f) => f.to_string(),
                None => value.to_string(),
            };
            match crate::hyper::Hyperlink::validate(&fmt) {
                Ok(()) => s.hyperlink_format = Some(fmt),
                Err(e) => return Err(pe(e)),
            }
        }
        "include-zero" => s.include_zero = Some(!negated),
        "line-buffered" => s.line_buffered = Some(!negated),
        "line-number" => s.line_number = Some(!negated),
        "no-line-number" => s.line_number = Some(false),
        "max-columns" => num!(max_columns),
        "max-columns-preview" => s.max_columns_preview = Some(!negated),
        "null" => s.null = Some(!negated),
        "only-matching" => s.only_matching = Some(!negated),
        "path-separator" => {
            if value.is_empty() {
                s.path_sep = Some(String::new());
            } else if value.len() != 1 {
                return Err(pe(format!(
                    "A path separator must be exactly one byte, but the given separator is {} bytes: {}\nIn some shells on Windows '/' is automatically expanded. Use '//' instead.",
                    value.len(),
                    value
                )));
            } else {
                s.path_sep = Some(value.to_string());
            }
        }
        "passthru" => s.passthru = Some(!negated),
        "pretty" => s.pretty = Some(!negated),
        "quiet" => s.quiet = Some(!negated),
        "replace" => s.replace = Some(value.to_string()),
        "sort" => {
            match value {
                "none" => s.sort = Some(SortBy::None),
                "path" => s.sort = Some(SortBy::Path),
                "modified" => s.sort = Some(SortBy::Modified),
                "accessed" => s.sort = Some(SortBy::Accessed),
                "created" => s.sort = Some(SortBy::Created),
                _ => return Err(pe(format!("choice '{}' is unrecognized", value))),
            };
            s.sortr = None;
            s.sort_files = None;
        }
        "sortr" => {
            match value {
                "none" => s.sortr = Some(SortBy::None),
                "path" => s.sortr = Some(SortBy::Path),
                "modified" => s.sortr = Some(SortBy::Modified),
                "accessed" => s.sortr = Some(SortBy::Accessed),
                "created" => s.sortr = Some(SortBy::Created),
                _ => return Err(pe(format!("choice '{}' is unrecognized", value))),
            };
            s.sort = None;
            s.sort_files = None;
        }
        "sort-files" => {
            s.sort_files = Some(!negated);
            s.sort = None;
            s.sortr = None;
        }
        "trim" => s.trim = Some(!negated),
        "vimgrep" => s.vimgrep = Some(!negated),
        "with-filename" => s.with_filename = Some(!negated),
        "no-filename" => s.with_filename = Some(false),
        "count" => s.out_mode = Some(OutMode::Count),
        "count-matches" => s.out_mode = Some(OutMode::CountMatches),
        "files-with-matches" => s.out_mode = Some(OutMode::FilesWithMatch),
        "files-without-match" => s.out_mode = Some(OutMode::FilesWithoutMatch),
        "json" => s.out_mode = Some(OutMode::Standard),
        "debug" => s.debug = !negated,
        "trace" => s.trace = !negated,
        "no-ignore-messages" => s.no_ignore_messages = Some(!negated),
        "ignore-messages" => s.no_ignore_messages = Some(false),
        "no-messages" => s.no_messages = Some(!negated),
        "messages" => s.no_messages = Some(false),
        "stats" => s.stats = Some(!negated),
        "files" => s.files = Some(!negated),
        "generate" => match value {
            "man" | "complete-bash" | "complete-zsh" | "complete-fish"
            | "complete-powershell" => s.generate = Some(value.to_string()),
            _ => return Err(pe(format!("choice '{}' is unrecognized", value))),
        },
        "no-config" => s.no_config = Some(!negated),
        "pcre2-version" => s.pcre2_version = Some(!negated),
        "type-list" => s.type_list = Some(!negated),
        "help" => s.help = true,
        "version" => s.version = true,
        _ => {}
    }
    Ok(())
}
EOF
echo ok"}

