                Ok(()) => s.hyperlink_format = Some(fmt),
                Err(e) => return Err(pe(e)),
            }
        }
        "include-zero" => s.include_zero = Some(!negated),
        "line-buffered" => s.line_buffered = Some(!negated),
        "line-number" => s.line_number = Some(!negated),
        "no-line-number" => s.line_number = Some(false),
        "max-columns" => num!(max_columns),
        "max-columns-preview" => s.max_columns_preview = Some(!negated),
        "null" => s.null = Some(!negated),
        "only-matching" => s.only_matching = Some(!negated),
        "path-separator" => {
            if value.is_empty() {
                s.path_sep = Some(String::new());
            } else if value.len() != 1 {
                return Err(pe(format!(
                    "A path separator must be exactly one byte, but the given separator is {} bytes: {}\nIn some shells on Windows '/' is automatically expanded. Use '//' instead.",
