        "no-ignore-messages" => s.no_ignore_messages = Some(!negated),
        "ignore-messages" => s.no_ignore_messages = Some(false),
        "no-messages" => s.no_messages = Some(!negated),
        "messages" => s.no_messages = Some(false),
        "stats" => s.stats = Some(!negated),
        "files" => s.files = Some(!negated),
