                })
                .collect()
        }
    }
}

fn utf16(data: &[u8], le: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(data.len());
    let mut i = 0;
    while i + 1 < data.len() {
        let hi = if le { data[i + 1] } else { data[i] };
        let lo = if le { data[i] } else { data[i + 1] };
        let unit = (hi as u32) << 8 | lo as u32;
        if (0xD800..0xDC00).contains(&unit) && i + 3 < data.len() {
            let hi2 = if le { data[i + 3] } else { data[i + 2] };
            let lo2 = if le { data[i + 2] } else { data[i + 3] };
            let unit2 = (hi2 as u32) << 8 | lo2 as u32;
            if (0xDC00..0xE000).contains(&unit2) {
                let c = 0x10000 + ((unit - 0xD800) << 10) + (unit2 - 0xDC00);
                push(&mut out, c);
                i += 4;
                continue;
            }
        }
        push(&mut out, unit);
        i += 2;
    }
    out
}

fn push(out: &mut Vec<u8>, c: u32) {
    if let Some(ch) = char::from_u32(c) {
        let mut buf = [0u8; 4];
        out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
    }
}
