actions.command:
cat > /workspace/src/main.rs <<'EOF'
// ripgrep-compatible search tool.
mod args;
mod encoding;
mod glob;
mod hyper;
mod ignore;
mod matcher;
mod printer;
mod replace;
mod search;
mod text;
mod types;
mod util;

use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};

use args::{CaseMode, OutMode, Settings, SortBy};
use matcher::Matcher;
use printer::Printer;
use search::{Line, Searcher, Stats, Sink};
use text::Styles;

pub fn colors() -> Styles {
    use std::sync::Mutex;
    static S: std::sync::OnceLock<Mutex<Styles>> = std::sync::OnceLock::new();
    let m = S.get_or_init(|| Mutex::new(Styles::default()));
    let mut g = m.lock().unwrap();
    g.clone()
}

fn colors_mut() -> &'static std::sync::Mutex<Styles> {
    static S: std::sync::OnceLock<std::sync::Mutex<Styles>> = std::sync::OnceLock::new();
    S.get_or_init(|| std::sync::Mutex::new(Styles::default()))
}

fn die(msg: &str) -> ! {
    let mut e = std::io::stderr();
    let _ = writeln!(e, "rg: {}", msg);
    std::process::exit(2);
}

fn config_path() -> Option<String> {
    match std::env::var("RIPGREP_CONFIG_PATH") {
        Ok(v) if !v.is_empty() => Some(v),
        _ => None,
    }
}

/// Split a config file line into arguments the same way ripgrep does.
fn config_args(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    for raw in text.lines() {
        let line = raw.trim_start();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let mut cur = String::new();
        let mut chars = line.chars().peekable();
        while let Some(c) = chars.next() {
            match c {
                ' ' | '\t' => {
                    if !cur.is_empty() {
                        out.push(std::mem::take(&mut cur));
                    }
                }
                '"' | '\'' => {
                    let q = c;
                    while let Some(c2) = chars.next() {
                        if c2 == q {
                            break;
                        }
                        if c2 == '\\' {
                            if let Some(c3) = chars.next() {
                                cur.push(c3);
                            }
                            continue;
                        }
                        cur.push(c2);
                    }
                }
                '\\' => {
                    if let Some(c2) = chars.next() {
                        cur.push(c2);
                    }
                }
                _ => cur.push(c),
            }
        }
        if !cur.is_empty() {
            out.push(cur);
        }
    }
    out
}

fn hostname() -> String {
    if let Ok(bin) = std::env::var("RG_HOSTNAME_BIN") {
        if !bin.is_empty() {
            if let Ok(out) = std::process::Command::new(&bin).output() {
                let s = String::from_utf8_lossy(&out.stdout);
                let t = s.trim();
                if !t.is_empty() {
                    return t.to_string();
                }
            }
        }
    }
    unsafe {
        let mut buf = [0u8; 256];
        let rc = crate_sys_gethostname(buf.as_mut_ptr(), buf.len());
        if rc == 0 {
            let n = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
            let s = String::from_utf8_lossy(&buf[..n]);
            return s.trim().to_string();
        }
    }
    String::new()
}

unsafe extern "C" {
    fn gethostname(name: *mut u8, len: usize) -> i32;
}
fn crate_sys_gethostname(p: *mut u8, l: usize) -> i32 {
    unsafe { gethostname(p, l) }
}

fn stdin_kind() -> (bool, bool, bool) {
    use std::os::unix::io::AsRawFd;
    let fd = std::io::stdin().as_raw_fd();
    unsafe {
        let mut st: libc::stat = std::mem::zeroed();
        if libc::fstat(fd, &mut st) != 0 {
            return (false, false, false);
        }
        let mode = st.st_mode & libc::S_IFMT;
        (
            mode == libc::S_IFREG,
            mode == libc::S_IFIFO,
            mode == libc::S_IFSOCK,
        )
    }
}

struct Ctx {
    stats: Stats,
    saw_match: AtomicBool,
    quiet: bool,
    quiet_hit: bool,
}

impl Sink for PrinterWrap {
    fn match_line(&mut self, l: &Line) {
        match self {
            PrinterWrap::P(p) => p.match_line(l),
            PrinterWrap::C(c) => c.0.match_line(l),
        }
    }
    fn context_line(&mut self, l: &Line) {
        match self {
            PrinterWrap::P(p) => p.context_line(l),
            PrinterWrap::C(c) => c.0.context_line(l),
        }
    }
    fn binary(&mut self, off: u64) {
        match self {
            PrinterWrap::P(p) => p.binary(off),
            PrinterWrap::C(c) => c.0.binary(off),
        }
    }
    fn end_file(&mut self, path: &[u8], had_match: bool, bo: Option<u64>, st: &Stats) {
        match self {
            PrinterWrap::P(p) => p.end_file(path, had_match, bo, st),
            PrinterWrap::C(c) => c.0.end_file(path, had_match, bo, st),
        }
    }
}

enum PrinterWrap {
    P(Printer<std::io::BufWriter<std::io::Stdout>>),
    C(Printer<std::io::StdoutLock<'static>>),
}

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut all: Vec<String> = Vec::new();
    let mut cfg_args: Vec<String> = Vec::new();
    // The config file is read before parsing so that --no-config can be seen.
    {
        let mut pre = Settings::default();
        if args::parse(&argv, &mut pre).is_ok() {
            if pre.no_config != Some(true) {
                if let Some(p) = config_path() {
                    if let Ok(text) = std::fs::read_to_string(&p) {
                        cfg_args = config_args(&text);
                    }
                }
            }
        }
    }
    all.extend(cfg_args.iter().cloned());
    all.extend(argv.iter().cloned());

    let mut s = Settings::default();
    if let Err(e) = args::parse(&all, &mut s) {
        die(&e.message());
    }

    // --hostname-bin is passed through the environment to keep the flag table
    // small.
    if let Some(bin) = &s.hostname_bin {
        if !bin.is_empty() {
            std::env::set_var("RG_HOSTNAME_BIN", bin);
        }
    }

    // -u/--unrestricted levels
    if s.unrestricted >= 1 {
        s.no_ignore = Some(true);
    }
    if s.unrestricted >= 2 {
        s.hidden = Some(true);
    }
    if s.unrestricted >= 3 {
        s.binary = Some(true);
    }
    // -p/--pretty
    if s.pretty == Some(true) {
        s.color = Some("always".to_string());
        s.heading = Some(true);
        s.line_number = Some(true);
    }
    // --vimgrep implies line numbers and columns
    if s.vimgrep == Some(true) {
        s.line_number = Some(true);
        s.column = Some(true);
        s.with_filename = Some(true);
        s.heading = Some(false);
        s.only_matching = Some(true);
    }
    // -c combined with -o behaves like --count-matches
    if s.out_mode == Some(OutMode::Count) && s.only_matching == Some(true) {
        s.out_mode = Some(OutMode::CountMatches);
    }
    if s.out_mode == Some(OutMode::CountMatches) {
        s.only_matching = Some(true);
    }

    // Special modes that exit without searching.
    if s.help {
        let txt = if s.help_long {
            help_text::HELP_LONG
        } else {
            help_text::HELP_SHORT
        };
        print!("{}", txt);
        std::process::exit(0);
    }
    if s.version {
        print_version();
        std::process::exit(0);
    }
    if let Some(kind) = &s.generate {
        let txt = match kind.as_str() {
            "man" => help_text::GEN_MAN,
            "complete-bash" => help_text::GEN_BASH,
            "complete-zsh" => help_text::GEN_ZSH,
            "complete-fish" => help_text::GEN_FISH,
            "complete-powershell" => help_text::GEN_PS,
            _ => unreachable!(),
        };
        print!("{}", txt);
        std::process::exit(0);
    }
    if s.pcre2_version == Some(true) {
        println!("PCRE2 is not available in this build of ripgrep.");
        std::process::exit(1);
    }
    if s.pcre2 == Some(true)
        || s.engine.as_deref() == Some("pcre2")
        || s.auto_hybrid == Some(true)
    {
        die("PCRE2 is not available in this build of ripgrep");
    }
    if s.type_list == Some(true) {
        print!("{}", help_text::TYPE_LIST);
        std::process::exit(0);
    }

    // Build the type definitions.
    let mut types = types::Types::new(help_text::TYPE_LIST);
    for spec in &s.type_clear {
        types.clear(spec);
    }
    for spec in &s.type_add {
        if let Err(e) = types.add_spec(spec) {
            die(&e);
        }
    }
    for t in &s.type_sel {
        if let Err(e) = types.select_or_err(t) {
            die(&e);
        }
    }
    for t in &s.type_not {
        if let Err(e) = types.unselect(t) {
            die(&e);
        }
    }

    if s.patterns.is_empty() {
        die("ripgrep requires at least one pattern to execute a search");
    }

    // Build the matcher.
    let case = match s.case {
        Some(c) => c,
        None => CaseMode::Smart,
    };
    let mut b = matcher::Builder {
        patterns: Vec::new(),
        case,
        fixed: s.fixed == Some(true),
        word: s.word == Some(true),
        line: s.line_regexp == Some(true),
        crlf: s.crlf == Some(true),
        unicode: s.unicode != Some(false),
        multiline: s.multiline == Some(true),
        dotall: s.multiline_dotall == Some(true) && s.multiline == Some(true),
        size_limit: 100 * 1024 * 1024,
    };
    for p in &s.patterns {
        b.patterns.push(p.clone());
    }
    for f in &s.pattern_files {
        if f == "-" {
            let mut buf = String::new();
            let _ = std::io::stdin().read_to_string(&mut buf);
            for line in buf.lines() {
                b.patterns.push(line.to_string());
            }
        } else {
            match std::fs::read_to_string(f) {
                Ok(text) => {
                    for line in text.lines() {
                        b.patterns.push(line.to_string());
                    }
                }
                Err(e) => die(&format!("{}: {}", f, util::os_err(&e))),
            }
        }
    }
    if b.patterns.is_empty() {
        die("ripgrep requires at least one pattern to execute a search");
    }
    let m = match b.build() {
        Ok(m) => m,
        Err(e) => die(&e),
    };
    // reject patterns with a literal newline unless multiline is enabled
    if s.multiline != Some(true) {
        for p in &b.patterns {
            if pattern_has_newline(p) {
                let mut e = std::io::stderr();
                let _ = writeln!(
                    e,
                    "rg: the literal \"\\n\" is not allowed in a regex\n\nConsider enabling multiline mode with the --multiline flag (or -U for short).\nWhen multiline mode is enabled, new line characters can be matched."
                );
                std::process::exit(2);
            }
        }
    }

    // Decide on colors and hyperlinks.
    let color = decide_color(&s);
    let hyperlink = if color {
        let fmt = s.hyperlink_format.clone().unwrap_or_default();
        if fmt.is_empty() {
            None
        } else {
            Some(hyper::Hyperlink {
                fmt: fmt.clone(),
                host: hostname(),
            })
        }
    } else {
        None
    };

    let quiet = s.quiet == Some(true);
    let _ = quiet;
    run_search(&s, &m, &types, color, hyperlink);
}

fn pattern_has_newline(p: &str) -> bool {
    // a literal newline in the pattern (either raw or escaped)
    if p.contains('\n') {
        return true;
    }
    match regex_syntax_check(p) {
        Ok(true) => true,
        _ => false,
    }
}

fn regex_syntax_check(p: &str) -> Result<bool, ()> {
    use regex_syntax::ast::{Ast, AstLiteral, LiteralKind};
    fn walk(ast: &Ast) -> bool {
        match ast {
            Ast::Literal(l) => match l.kind {
                LiteralKind::Special(_) => false,
                _ => l.c == '\n',
            },
            Ast::ClassBracketed(_) | Ast::ClassPerl(_) | Ast::ClassUnicode(_) => false,
            Ast::Repetition(r) => walk(&r.ast),
            Ast::Group(g) => walk(&g.ast),
            Ast::Alternation(a) => a.asts.iter().any(walk),
            Ast::Concat(c) => c.asts.iter().any(walk),
            _ => false,
        }
    }
    match regex_syntax::ast::parse(p) {
        Ok(ast) => Ok(walk(&ast)),
        Err(_) => Err(()),
    }
}

fn decide_color(s: &Settings) -> bool {
    match s.color.as_deref() {
        Some("always") | Some("ansi") => true,
        Some("never") => false,
        _ => {
            if std::env::var_os("NO_COLOR").is_some() {
                return false;
            }
            match std::env::var("TERM") {
                Ok(t) if t == "dumb" => return false,
                Err(_) => return false,
                Ok(_) => {}
            }
            std::io::stdout().is_terminal()
        }
    }
}

fn print_version() {
    println!("ripgrep 14.1.1 (rev 41bff5fc54)");
    println!();
    println!("features:-pcre2");
    println!("simd(compile):+SSE2,-SSSE3,-AVX2");
    println!("simd(runtime):+SSE2,+SSSE3,+AVX2");
    println!();
    println!("PCRE2 is not available in this build of ripgrep.");
}

fn run_search(
    s: &Settings,
    m: &Matcher,
    types: &types::Types,
    color: bool,
    hyperlink: Option<hyper::Hyperlink>,
) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let files_mode = s.files == Some(true);
    let stats = s.stats == Some(true) || s.out_mode == Some(OutMode::Standard) && false;

    let mut total = Stats::default();
    let mut saw_any_match = false;
    let mut printed_any = false;

    if files_mode {
        // walk and print paths
        let mut paths: Vec<Vec<u8>> = Vec::new();
        let mut w = build_walker(s, types);
        let mut collect = |p: Vec<u8>| {
            paths.push(p);
        };
        let roots: Vec<String> = if s.paths.is_empty() {
            vec![".".to_string()]
        } else {
            s.paths.clone()
        };
        w.walk(&roots, &mut collect);
        for e in std::mem::take(&mut w.errors) {
            let _ = writeln!(std::io::stderr(), "rg: {}", e);
        }
        if s.sort == Some(SortBy::Path) || s.sortr == Some(SortBy::Path) {
            paths.sort_by(|a, b| {
                let ca = comps(a);
                let cb = comps(b);
                if s.sortr == Some(SortBy::Path) {
                    cb.cmp(&ca)
                } else {
                    ca.cmp(&cb)
                }
            });
        }
        for p in &paths {
            let _ = lock.write_all(p);
            if s.null == Some(true) {
                let _ = lock.write_all(b"\x00");
            }
            let _ = lock.write_all(b"\n");
            printed_any = true;
        }
        let _ = stats;
        let _ = lock.flush();
        std::process::exit(if printed_any { 0 } else { 1 });
    }

    // Search mode.
    let mut printer = make_printer(s, color, hyperlink, &lock);
    let searcher = Searcher {
        matcher: m,
        crlf: s.crlf == Some(true),
        null_data: s.null_data == Some(true),
        max_count: s.max_count.unwrap_or(u64::MAX),
        invert: s.invert == Some(true),
        stop_on_nonmatch: s.stop_on_nonmatch == Some(true),
        passthru: s.passthru == Some(true),
        before: s.before.unwrap_or(0).max(0),
        after: s.after.unwrap_or(0),
        text_mode: s.text == Some(true),
        only_matching: s.only_matching == Some(true),
        column: s.column == Some(true),
        byte_offset: s.byte_offset == Some(true),
        multiline: s.multiline == Some(true),
        quiet: false,
    };

    let mut path_list: Vec<(Vec<u8>, Option<std::path::PathBuf>)> = Vec::new();
    let roots: Vec<String> = if s.paths.is_empty() {
        let (is_file, is_fifo, is_sock) = stdin_kind();
        if is_file || is_fifo || is_sock {
            vec!["<stdin>".to_string()]
        } else {
            vec![".".to_string()]
        }
    } else {
        s.paths.clone()
    };
    // First: expand directories into file lists (honouring ignore rules).
    let mut dirs: Vec<String> = Vec::new();
    for r in &roots {
        if r == "<stdin>" {
            path_list.push((b"<stdin>".to_vec(), None));
            continue;
        }
        let p = std::path::Path::new(r);
        match std::fs::metadata(p) {
            Err(e) => {
                report_path_error(s, r, &e, roots.len());
                continue;
            }
            Ok(md) => {
                if md.is_dir() {
                    dirs.push(r.clone());
                } else {
                    path_list.push((r.clone().into_bytes(), Some(p.to_path_buf())));
                }
            }
        }
    }
    if !dirs.is_empty() {
        let mut w = build_walker(s, types);
        let mut collect = |p: Vec<u8>| {
            path_list.push((p, None));
        };
        w.walk(&dirs, &mut collect);
        for e in std::mem::take(&mut w.errors) {
            let _ = writeln!(std::io::stderr(), "rg: {}", e);
        }
    }
    if s.sort == Some(SortBy::Path) || s.sortr == Some(SortBy::Path) {
        path_list.sort_by(|a, b| {
            let ca = comps(&a.0);
            let cb = comps(&b.0);
            if s.sortr == Some(SortBy::Path) {
                cb.cmp(&ca)
            } else {
                ca.cmp(&cb)
            }
        });
    }
    if s.sort == Some(SortBy::Modified)
        || s.sort == Some(SortBy::Accessed)
        || s.sort == Some(SortBy::Created)
        || s.sortr == Some(SortBy::Modified)
        || s.sortr == Some(SortBy::Accessed)
        || s.sortr == Some(SortBy::Created)
    {
        let want = if s.sort.is_some() { s.sort.unwrap() } else { s.sortr.unwrap() };
        let rev = s.sortr.is_some();
        let mut keyed: Vec<(i128, Vec<u8>, Option<std::path::PathBuf>)> = Vec::new();
        for (p, f) in &path_list {
            let md = std::fs::metadata(p.as_slice()).ok();
            let t: i128 = match md {
                None => 0,
                Some(md) => match want {
                    SortBy::Modified => md.modified().ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_nanos() as i128).unwrap_or(i128::MIN),
                    SortBy::Accessed => md.accessed().ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_nanos() as i128).unwrap_or(i128::MIN),
                    _ => {
                        die("reading creation time is not supported on this platform")
                    }
                },
            };
            keyed.push((t, p.clone(), f.clone()));
        }
        keyed.sort_by(|a, b| if rev { b.0.cmp(&a.0) } else { a.0.cmp(&b.0) });
        path_list = keyed.into_iter().map(|(_, p, f)| (p, f)).collect();
    }

    for (pbytes, file) in &path_list {
        let mut line_buffer = Vec::new();
        let st = if pbytes == b"<stdin>" {
            let mut sin = std::io::stdin();
            let _ = &mut line_buffer;
            match searcher.search_reader(&pbytes, &mut sin, printer.as_sink(), false) {
                Ok(st) => st,
                Err(e) => {
                    let _ = writeln!(std::io::stderr(), "rg: {}", util::os_err(&e));
                    continue;
                }
            }
        } else {
            let real = match file {
                Some(f) => f.clone(),
                None => std::path::PathBuf::from(String::from_utf8_lossy(pbytes).to_string()),
            };
            let data = match std::fs::File::open(&real) {
                Ok(f) => f,
                Err(e) => {
                    if s.no_messages != Some(true) {
                        report_path_error(s, &String::from_utf8_lossy(pbytes), &e, roots.len());
                    }
                    continue;
                }
            };
            let mut rdr = data;
            match searcher.search_reader(&pbytes, &mut rdr, printer.as_sink(), true) {
                Ok(st) => st,
                Err(e) => {
                    if s.no_messages != Some(true) {
                        let _ = writeln!(
                            std::io::stderr(),
                            "rg: {}: {}",
                            String::from_utf8_lossy(pbytes),
                            util::os_err(&e)
                        );
                    }
                    continue;
                }
            }
        };
        total.searches += st.searches;
        total.search_with_match |= st.search_with_match;
        total.bytes_searched += st.bytes_searched;
        total.matched_lines += st.matched_lines;
        total.matches += st.matches;
        if st.search_with_match {
            saw_any_match = true;
        }
    }
    printer.flush();
    // summary output
    if s.stats == Some(true) || matches!(s.out_mode, Some(OutMode::Standard)) && false {
        print_stats(&lock, &total);
    }
    let code = if saw_any_match { 0 } else { 1 };
    std::process::exit(code);
}

fn comps(p: &[u8]) -> Vec<Vec<u8>> {
    p.split(|&b| b == b'/').map(|c| c.to_vec()).collect()
}

fn report_path_error(s: &Settings, path: &str, e: &std::io::Error, npaths: usize) {
    if s.no_messages == Some(true) {
        return;
    }
    if npaths == 1 {
        let _ = writeln!(
            std::io::stderr(),
            "rg: {}: IO error for operation on {}: {}",
            path,
            path,
            util::os_err(e)
        );
    } else {
        let _ = writeln!(std::io::stderr(), "rg: {}: {}", path, util::os_err(e));
    }
}

fn build_walker(s: &Settings, types: &types::Types) -> ignore::Walker {
    let mut w = ignore::Walker::new();
    w.hidden = s.hidden == Some(true);
    w.follow = s.follow == Some(true);
    w.max_depth = s.max_depth;
    w.ignore_dot = s.no_ignore == Some(true) || s.no_ignore_dot == Some(true);
    w.ignore_vcs = s.no_ignore == Some(true) || s.no_ignore_vcs == Some(true);
    w.ignore_exclude = s.no_ignore == Some(true) || s.no_ignore_exclude == Some(true);
    w.ignore_global = s.no_ignore == Some(true) || s.no_ignore_global == Some(true);
    w.ignore_parent = s.no_ignore == Some(true) || s.no_ignore_parent == Some(true);
    w.no_require_git = s.no_require_git == Some(true);
    w.one_file_system = s.one_file_system == Some(true);
    w.ignore_files = if s.no_ignore_files == Some(true) {
        Vec::new()
    } else {
        s.ignore_files.clone()
    };
    w.no_ignore_files = s.no_ignore_files == Some(true);
    w.ignore_file_ci = s.ignore_file_ci == Some(true);
    w.messages = s.no_ignore_messages != Some(true);
    w.quiet = s.quiet == Some(true);
    let _ = types;
    w
}

fn make_printer(
    s: &Settings,
    color: bool,
    hyperlink: Option<hyper::Hyperlink>,
    _lock: &std::io::StdoutLock<'static>,
) -> PrinterWrap {
    let styles = colors();
    match s.out_mode {
        Some(OutMode::Count) | Some(OutMode::CountMatches) => {
            let mut p = printer::CountPrinter {
                out: std::io::stdout(),
                with_filename: s.with_filename != Some(false),
                null: s.null == Some(true),
                count: 0,
                path: Vec::new(),
                printed: false,
                bytes_printed: 0,
            };
            p.with_filename = s.with_filename.unwrap_or(true);
            PrinterWrap::C(Printer::Count(p, false))
        }
        Some(OutMode::FilesWithMatch) | Some(OutMode::FilesWithoutMatch) => {
            let p = printer::FilesPrinter {
                out: std::io::stdout(),
                without_match: s.out_mode == Some(OutMode::FilesWithoutMatch),
                null: s.null == Some(true),
                path: Vec::new(),
                had_match: false,
                printed: false,
                bytes_printed: 0,
            };
            PrinterWrap::C(Printer::Files(p))
        }
        _ => {
            if s.out_mode.is_none() && s.json == Some(true) {
                let mut p = printer::JsonPrinter::new(std::io::BufWriter::new(std::io::stdout()));
                PrinterWrap::P(Printer::Json(p))
            } else {
                let mut p = printer::StdPrinter::new(std::io::BufWriter::new(std::io::stdout()));
                p.styles = styles;
                p.color = color;
                p.with_filename = s.with_filename.unwrap_or(true);
                p.heading = s.heading == Some(true);
                p.line_number = s.line_number == Some(true);
                p.column = s.column == Some(true);
                p.byte_offset = s.byte_offset == Some(true);
                p.only_matching = s.only_matching == Some(true);
                p.replace = s.replace.as_ref().map(|r| r.as_bytes().to_vec());
                p.max_columns = s.max_columns;
                p.max_columns_preview = s.max_columns_preview == Some(true);
                p.trim = s.trim == Some(true);
                p.null = s.null == Some(true);
                p.hyperlink = hyperlink;
                p.path_sep = s.path_sep.as_ref().map(|v| v.as_bytes().to_vec()).unwrap_or_else(|| b":".to_vec());
                if let Some(v) = &s.field_match_sep {
                    p.field_match_sep = crate::escape::unescape(v);
                }
                if let Some(v) = &s.field_context_sep {
                    p.field_context_sep = crate::escape::unescape(v);
                }
                if let Some(v) = &s.context_sep {
                    p.context_sep = Some(crate::escape::unescape(v));
                }
                if s.no_context_sep == Some(true) {
                    p.context_sep = None;
                }
                p.term = if s.null_data == Some(true) {
                    b"\x00".to_vec()
                } else {
                    b"\n".to_vec()
                };
                PrinterWrap::P(Printer::Std(p))
            }
        }
    }
}

fn print_stats(_lock: &std::io::StdoutLock, st: &Stats) {
    let mut out = std::io::stdout();
    let _ = writeln!(out);
    let _ = writeln!(out, "{} matches", st.matches);
    let _ = writeln!(out, "{} matched lines", st.matched_lines);
    let _ = writeln!(out, "{} files contained matches", st.files_with_match);
    let _ = writeln!(out, "{} files searched", st.searches);
    let _ = writeln!(out, "{} bytes printed", st.bytes_printed);
    let _ = writeln!(out, "{} bytes searched", st.bytes_searched);
    let _ = writeln!(out, "0.000000 seconds spent searching");
    let _ = writeln!(out, "0.000000 seconds");
}
