/// Split a config file line into arguments the same way ripgrep does.
fn config_args(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    for raw in text.lines() {
        let line = raw.trim_start();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let mut cur = String::new();
        let mut chars = line.chars().peekable();
        while let Some(c) = chars.next() {
            match c {
                ' ' | '\t' => {
                    if !cur.is_empty() {
                        out.push(std::mem::take(&mut cur));
                    }
                }
                '"' | '\'' => {
                    let q = c;
                    while let Some(c2) = chars.next() {
                        if c2 == q {
                            break;
                        }
                        if c2 == '\\' {
                            if let Some(c3) = chars.next() {
                                cur.push(c3);
                            }
                            continue;
                        }
                        cur.push(c2);
                    }
                }
                '\\' => {
                    if let Some(c2) = chars.next() {
                        cur.push(c2);
                    }
                }
                _ => cur.push(c),
            }
        }
        if !cur.is_empty() {
            out.push(cur);
        }
    }
    out
}

fn hostname() -> String {
    if let Ok(bin) = std::env::var("RG_HOSTNAME_BIN") {
        if !bin.is_empty() {
            if let Ok(out) = std::process::Command::new(&bin).output() {
                let s = String::from_utf8_lossy(&out.stdout);
                let t = s.trim();
                if !t.is_empty() {
                    return t.to_string();
                }
            }
        }
    }
    unsafe {
        let mut buf = [0u8; 256];
        let rc = crate_sys_gethostname(buf.as_mut_ptr(), buf.len());
        if rc == 0 {
            let n = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
            let s = String::from_utf8_lossy(&buf[..n]);
            return s.trim().to_string();
        }
    }
    String::new()
}

unsafe extern "C" {
    fn gethostname(name: *mut u8, len: usize) -> i32;
}
fn crate_sys_gethostname(p: *mut u8, l: usize) -> i32 {
