    }
    fn context_line(&mut self, l: &Line) {
        match self {
            PrinterWrap::P(p) => p.context_line(l),
            PrinterWrap::C(c) => c.0.context_line(l),
        }
    }
    fn binary(&mut self, off: u64) {
