    };
    let mut b = matcher::Builder {
        patterns: Vec::new(),
        case,
        fixed: s.fixed == Some(true),
        word: s.word == Some(true),
        line: s.line_regexp == Some(true),
        crlf: s.crlf == Some(true),
        unicode: s.unicode != Some(false),
