    let _ = quiet;
    run_search(&s, &m, &types, color, hyperlink);
}

fn pattern_has_newline(p: &str) -> bool {
    // a literal newline in the pattern (either raw or escaped)
    if p.contains('\n') {
        return true;
    }
    match regex_syntax_check(p) {
        Ok(true) => true,
        _ => false,
    }
}

fn regex_syntax_check(p: &str) -> Result<bool, ()> {
    use regex_syntax::ast::{Ast, AstLiteral, LiteralKind};
    fn walk(ast: &Ast) -> bool {
        match ast {
            Ast::Literal(l) => match l.kind {
                LiteralKind::Special(_) => false,
                _ => l.c == '\n',
            },
            Ast::ClassBracketed(_) | Ast::ClassPerl(_) | Ast::ClassUnicode(_) => false,
            Ast::Repetition(r) => walk(&r.ast),
            Ast::Group(g) => walk(&g.ast),
            Ast::Alternation(a) => a.asts.iter().any(walk),
            Ast::Concat(c) => c.asts.iter().any(walk),
            _ => false,
        }
    }
    match regex_syntax::ast::parse(p) {
        Ok(ast) => Ok(walk(&ast)),
        Err(_) => Err(()),
    }
}

fn decide_color(s: &Settings) -> bool {
    match s.color.as_deref() {
        Some("always") | Some("ansi") => true,
        Some("never") => false,
        _ => {
            if std::env::var_os("NO_COLOR").is_some() {
                return false;
            }
            match std::env::var("TERM") {
                Ok(t) if t == "dumb" => return false,
                Err(_) => return false,
                Ok(_) => {}
            }
            std::io::stdout().is_terminal()
        }
    }
}

fn print_version() {
    println!("ripgrep 14.1.1 (rev 41bff5fc54)");
    println!();
    println!("features:-pcre2");
    println!("simd(compile):+SSE2,-SSSE3,-AVX2");
    println!("simd(runtime):+SSE2,+SSSE3,+AVX2");
    println!();
    println!("PCRE2 is not available in this build of ripgrep.");
}

fn run_search(
    s: &Settings,
    m: &Matcher,
    types: &types::Types,
    color: bool,
    hyperlink: Option<hyper::Hyperlink>,
) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let files_mode = s.files == Some(true);
    let stats = s.stats == Some(true) || s.out_mode == Some(OutMode::Standard) && false;

    let mut total = Stats::default();
    let mut saw_any_match = false;
    let mut printed_any = false;

    if files_mode {
        // walk and print paths
        let mut paths: Vec<Vec<u8>> = Vec::new();
        let mut w = build_walker(s, types);
        let mut collect = |p: Vec<u8>| {
            paths.push(p);
        };
        let roots: Vec<String> = if s.paths.is_empty() {
            vec![".".to_string()]
        } else {
            s.paths.clone()
        };
        w.walk(&roots, &mut collect);
        for e in std::mem::take(&mut w.errors) {
            let _ = writeln!(std::io::stderr(), "rg: {}", e);
        }
        if s.sort == Some(SortBy::Path) || s.sortr == Some(SortBy::Path) {
            paths.sort_by(|a, b| {
                let ca = comps(a);
                let cb = comps(b);
                if s.sortr == Some(SortBy::Path) {
                    cb.cmp(&ca)
                } else {
                    ca.cmp(&cb)
                }
            });
        }
        for p in &paths {
            let _ = lock.write_all(p);
            if s.null == Some(true) {
                let _ = lock.write_all(b"\x00");
            }
            let _ = lock.write_all(b"\n");
            printed_any = true;
        }
        let _ = stats;
        let _ = lock.flush();
        std::process::exit(if printed_any { 0 } else { 1 });
    }

    // Search mode.
    let mut printer = make_printer(s, color, hyperlink, &lock);
    let searcher = Searcher {
        matcher: m,
        crlf: s.crlf == Some(true),
        null_data: s.null_data == Some(true),
        max_count: s.max_count.unwrap_or(u64::MAX),
        invert: s.invert == Some(true),
        stop_on_nonmatch: s.stop_on_nonmatch == Some(true),
        passthru: s.passthru == Some(true),
        before: s.before.unwrap_or(0).max(0),
        after: s.after.unwrap_or(0),
        text_mode: s.text == Some(true),
        only_matching: s.only_matching == Some(true),
        column: s.column == Some(true),
        byte_offset: s.byte_offset == Some(true),
        multiline: s.multiline == Some(true),
        quiet: false,
    };

    let mut path_list: Vec<(Vec<u8>, Option<std::path::PathBuf>)> = Vec::new();
    let roots: Vec<String> = if s.paths.is_empty() {
        let (is_file, is_fifo, is_sock) = stdin_kind();
        if is_file || is_fifo || is_sock {
            vec!["<stdin>".to_string()]
        } else {
            vec![".".to_string()]
        }
    } else {
        s.paths.clone()
    };
    // First: expand directories into file lists (honouring ignore rules).
    let mut dirs: Vec<String> = Vec::new();
    for r in &roots {
        if r == "<stdin>" {
            path_list.push((b"<stdin>".to_vec(), None));
            continue;
        }
        let p = std::path::Path::new(r);
        match std::fs::metadata(p) {
            Err(e) => {
                report_path_error(s, r, &e, roots.len());
                continue;
            }
            Ok(md) => {
                if md.is_dir() {
                    dirs.push(r.clone());
                } else {
                    path_list.push((r.clone().into_bytes(), Some(p.to_path_buf())));
                }
            }
        }
    }
    if !dirs.is_empty() {
        let mut w = build_walker(s, types);
        let mut collect = |p: Vec<u8>| {
            path_list.push((p, None));
        };
        w.walk(&dirs, &mut collect);
        for e in std::mem::take(&mut w.errors) {
            let _ = writeln!(std::io::stderr(), "rg: {}", e);
        }
    }
    if s.sort == Some(SortBy::Path) || s.sortr == Some(SortBy::Path) {
        path_list.sort_by(|a, b| {
            let ca = comps(&a.0);
            let cb = comps(&b.0);
            if s.sortr == Some(SortBy::Path) {
                cb.cmp(&ca)
            } else {
                ca.cmp(&cb)
            }
        });
    }
    if s.sort == Some(SortBy::Modified)
        || s.sort == Some(SortBy::Accessed)
        || s.sort == Some(SortBy::Created)
        || s.sortr == Some(SortBy::Modified)
        || s.sortr == Some(SortBy::Accessed)
        || s.sortr == Some(SortBy::Created)
    {
        let want = if s.sort.is_some() { s.sort.unwrap() } else { s.sortr.unwrap() };
        let rev = s.sortr.is_some();
        let mut keyed: Vec<(i128, Vec<u8>, Option<std::path::PathBuf>)> = Vec::new();
        for (p, f) in &path_list {
            let md = std::fs::metadata(p.as_slice()).ok();
            let t: i128 = match md {
                None => 0,
                Some(md) => match want {
                    SortBy::Modified => md.modified().ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_nanos() as i128).unwrap_or(i128::MIN),
                    SortBy::Accessed => md.accessed().ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_nanos() as i128).unwrap_or(i128::MIN),
                    _ => {
                        die("reading creation time is not supported on this platform")
                    }
                },
            };
            keyed.push((t, p.clone(), f.clone()));
        }
        keyed.sort_by(|a, b| if rev { b.0.cmp(&a.0) } else { a.0.cmp(&b.0) });
        path_list = keyed.into_iter().map(|(_, p, f)| (p, f)).collect();
    }

    for (pbytes, file) in &path_list {
        let mut line_buffer = Vec::new();
        let st = if pbytes == b"<stdin>" {
            let mut sin = std::io::stdin();
            let _ = &mut line_buffer;
            match searcher.search_reader(&pbytes, &mut sin, printer.as_sink(), false) {
                Ok(st) => st,
                Err(e) => {
                    let _ = writeln!(std::io::stderr(), "rg: {}", util::os_err(&e));
                    continue;
                }
            }
        } else {
            let real = match file {
                Some(f) => f.clone(),
                None => std::path::PathBuf::from(String::from_utf8_lossy(pbytes).to_string()),
            };
            let data = match std::fs::File::open(&real) {
                Ok(f) => f,
                Err(e) => {
                    if s.no_messages != Some(true) {
                        report_path_error(s, &String::from_utf8_lossy(pbytes), &e, roots.len());
                    }
                    continue;
                }
            };
            let mut rdr = data;
            match searcher.search_reader(&pbytes, &mut rdr, printer.as_sink(), true) {
                Ok(st) => st,
                Err(e) => {
                    if s.no_messages != Some(true) {
                        let _ = writeln!(
                            std::io::stderr(),
                            "rg: {}: {}",
                            String::from_utf8_lossy(pbytes),
                            util::os_err(&e)
                        );
                    }
                    continue;
                }
            }
        };
        total.searches += st.searches;
        total.search_with_match |= st.search_with_match;
        total.bytes_searched += st.bytes_searched;
        total.matched_lines += st.matched_lines;
        total.matches += st.matches;
        if st.search_with_match {
            saw_any_match = true;
        }
    }
    printer.flush();
    // summary output
    if s.stats == Some(true) || matches!(s.out_mode, Some(OutMode::Standard)) && false {
        print_stats(&lock, &total);
    }
    let code = if saw_any_match { 0 } else { 1 };
    std::process::exit(code);
}

fn comps(p: &[u8]) -> Vec<Vec<u8>> {
    p.split(|&b| b == b'/').map(|c| c.to_vec()).collect()
}

fn report_path_error(s: &Settings, path: &str, e: &std::io::Error, npaths: usize) {
    if s.no_messages == Some(true) {
        return;
    }
    if npaths == 1 {
        let _ = writeln!(
            std::io::stderr(),
            "rg: {}: IO error for operation on {}: {}",
            path,
            path,
            util::os_err(e)
        );
    } else {
        let _ = writeln!(std::io::stderr(), "rg: {}: {}", path, util::os_err(e));
    }
}

fn build_walker(s: &Settings, types: &types::Types) -> ignore::Walker {
    let mut w = ignore::Walker::new();
    w.hidden = s.hidden == Some(true);
    w.follow = s.follow == Some(true);
    w.max_depth = s.max_depth;
    w.ignore_dot = s.no_ignore == Some(true) || s.no_ignore_dot == Some(true);
    w.ignore_vcs = s.no_ignore == Some(true) || s.no_ignore_vcs == Some(true);
    w.ignore_exclude = s.no_ignore == Some(true) || s.no_ignore_exclude == Some(true);
    w.ignore_global = s.no_ignore == Some(true) || s.no_ignore_global == Some(true);
    w.ignore_parent = s.no_ignore == Some(true) || s.no_ignore_parent == Some(true);
    w.no_require_git = s.no_require_git == Some(true);
    w.one_file_system = s.one_file_system == Some(true);
    w.ignore_files = if s.no_ignore_files == Some(true) {
        Vec::new()
    } else {
        s.ignore_files.clone()
    };
    w.no_ignore_files = s.no_ignore_files == Some(true);
    w.ignore_file_ci = s.ignore_file_ci == Some(true);
    w.messages = s.no_ignore_messages != Some(true);
    w.quiet = s.quiet == Some(true);
    let _ = types;
    w
}

fn make_printer(
    s: &Settings,
    color: bool,
    hyperlink: Option<hyper::Hyperlink>,
    _lock: &std::io::StdoutLock<'static>,
) -> PrinterWrap {
    let styles = colors();
    match s.out_mode {
        Some(OutMode::Count) | Some(OutMode::CountMatches) => {
            let mut p = printer::CountPrinter {
                out: std::io::stdout(),
                with_filename: s.with_filename != Some(false),
                null: s.null == Some(true),
                count: 0,
                path: Vec::new(),
                printed: false,
                bytes_printed: 0,
            };
            p.with_filename = s.with_filename.unwrap_or(true);
            PrinterWrap::C(Printer::Count(p, false))
        }
        Some(OutMode::FilesWithMatch) | Some(OutMode::FilesWithoutMatch) => {
            let p = printer::FilesPrinter {
                out: std::io::stdout(),
                without_match: s.out_mode == Some(OutMode::FilesWithoutMatch),
                null: s.null == Some(true),
                path: Vec::new(),
                had_match: false,
                printed: false,
                bytes_printed: 0,
            };
            PrinterWrap::C(Printer::Files(p))
        }
        _ => {
            if s.out_mode.is_none() && s.json == Some(true) {
                let mut p = printer::JsonPrinter::new(std::io::BufWriter::new(std::io::stdout()));
                PrinterWrap::P(Printer::Json(p))
            } else {
                let mut p = printer::StdPrinter::new(std::io::BufWriter::new(std::io::stdout()));
                p.styles = styles;
                p.color = color;
                p.with_filename = s.with_filename.unwrap_or(true);
                p.heading = s.heading == Some(true);
                p.line_number = s.line_number == Some(true);
                p.column = s.column == Some(true);
                p.byte_offset = s.byte_offset == Some(true);
                p.only_matching = s.only_matching == Some(true);
                p.replace = s.replace.as_ref().map(|r| r.as_bytes().to_vec());
                p.max_columns = s.max_columns;
                p.max_columns_preview = s.max_columns_preview == Some(true);
                p.trim = s.trim == Some(true);
                p.null = s.null == Some(true);
                p.hyperlink = hyperlink;
                p.path_sep = s.path_sep.as_ref().map(|v| v.as_bytes().to_vec()).unwrap_or_else(|| b":".to_vec());
                if let Some(v) = &s.field_match_sep {
                    p.field_match_sep = crate::escape::unescape(v);
                }
                if let Some(v) = &s.field_context_sep {
                    p.field_context_sep = crate::escape::unescape(v);
                }
                if let Some(v) = &s.context_sep {
                    p.context_sep = Some(crate::escape::unescape(v));
                }
                if s.no_context_sep == Some(true) {
                    p.context_sep = None;
                }
                p.term = if s.null_data == Some(true) {
                    b"\x00".to_vec()
                } else {
                    b"\n".to_vec()
                };
                PrinterWrap::P(Printer::Std(p))
            }
        }
    }
}

fn print_stats(_lock: &std::io::StdoutLock, st: &Stats) {
    let mut out = std::io::stdout();
    let _ = writeln!(out);
    let _ = writeln!(out, "{} matches", st.matches);
    let _ = writeln!(out, "{} matched lines", st.matched_lines);
    let _ = writeln!(out, "{} files contained matches", st.files_with_match);
    let _ = writeln!(out, "{} files searched", st.searches);
    let _ = writeln!(out, "{} bytes printed", st.bytes_printed);
    let _ = writeln!(out, "{} bytes searched", st.bytes_searched);
    let _ = writeln!(out, "0.000000 seconds spent searching");
    let _ = writeln!(out, "0.000000 seconds");
}
